-- Generated by scripts/pages.ts from i18n/deDE/recipes/: edit those, not this file.
-- pages[chef][spell] = { paragraph, ... }: the chef's page of each dish.
local _, ns = ...
ns.pages = {
  kendor = {
    [2538] = { "Jeder Koch beginnt hier, mit einem Feuer, einem Messer und einem Wolf, der nicht zum Abendessen werden wollte. Die meisten kommen nie darüber hinaus, und so kam es, dass die Straßen dieses Königreichs nach verbranntem Wolf riechen. Verkohlen ist nicht Verbrennen. Ihr wollt die Außenseite dunkel und knusprig und das Innere noch nachgiebig, und das verlangt ein Feuer, das sich zu Glut beruhigt hat, nicht eines, das noch mit seinen Flammen angibt. Lernt das, und Ihr habt Geduld gelernt. Dann kommt zu mir." },
    [2539] = { "Das zweite Gericht, das jeder Lehrer lehrt, und das erste, das die meisten Köche falsch machen. Sie glauben, Gewürze seien eine Verkleidung. Sie nehmen einen Wolf, der sich in den Hügeln mager gelaufen hat, und begraben ihn, und der Wolf hatte Besseres verdient. Reibt die Gewürze ein, bevor das Fleisch das Feuer trifft, und lasst sie dann einziehen. Am Ende hinzugefügte Gewürze sitzen auf dem Fleisch wie ein Hut. Am Anfang hinzugefügte Gewürze werden ein Teil davon." },
    [2540] = { "Die Eber des Waldes von Elwynn haben diese Stadt ernährt, seit bevor sie Mauern hatte, und sie werden sie ernähren, wenn die Mauern wieder einmal neu gebaut werden müssen. Tomas in Goldhain röstet sie im Ganzen für sein Gasthaus, dreht den Spieß von Hand und nennt es Tradition. Es ist eine schöne Tradition. Es ist auch der Grund, warum sein Eber auf der einen Seite gar ist und auf der anderen voller Hoffnung. Schneidet das Fleisch in gleichmäßige Stücke, damit die Hitze sie alle gleich behandelt. Gerechtigkeit ist in der Küche eine Frage der Messerarbeit." },
    [2541] = { "Die Kojoten von Westfall fressen, was immer die Bauern zurückgelassen haben, und das Fleisch schmeckt nach einem harten Leben. Seine Vergangenheit könnt Ihr nicht ändern. Ihr könnt sie achten. Schneidet das Steak dick, bratet es scharf an und nehmt es von der Hitze, solange die Mitte noch errötet. Ein dünnes, durchgebratenes Kojotensteak ist eine Sandale. Ein dickes, das geruht hat, ist ein Abendessen. Jeder Lehrling kommt mit der Vorstellung zu mir, ein Steak sei eine einfache Sache. Das ist es. Darum ist es so leicht zu verderben." },
    [2542] = { "Die Pastete aus Geiferzahnleber ist der Stolz der Höfe von Westfall, oder war er, als es in Westfall noch Höfe gab, auf die man stolz sein konnte. Eine Bäuerin an der Küstenstraße hat sie der halben Provinz beigebracht, und ich verkaufe sie hier mit einigen Verbesserungen, die sie bisher nicht in Sturmwind angefochten hat. Die Leber eines Geiferzahns ist kräftig, dunkel und reichhaltig, und sie muss vor dem Kochen in kaltem Wasser liegen, damit ihre Bitterkeit herausgezogen wird. Dann eine Prise milder Gewürze und ein langsamer Ofen. Schnell gegarte Leber wird grau und körnig und schmeckt nach Eisen. Langsam gegarte Leber wird weich und süß und schmeckt nach dem Hof, von dem sie kommt. Über die Kruste lässt sich streiten. Über die Leber nicht. Wenn die Pastete aus dem Ofen kommt, lasst sie ruhen, bis sie aufhört zu flüstern. Dann schneidet sie an, und dann dürft Ihr stolz sein." },
    [2543] = { "Ich verkaufe das Rezept für diesen Eintopf, was Euch sagt, dass ich ihn gutheiße, so wie man ein festes Paar Stiefel gutheißt. Die Bauern von Westfall machten ihn aus dem, was das Land ihnen hinwarf, dem Geier, der Schnauze eines Geiferzahns, dem Auge des Murlocs, und sie hatten mit allen dreien recht. Ich habe ihn einmal ohne das Auge versucht. Er war dünn, und mein Stolz auch. Das Auge gibt der Brühe ihre Kraft. Lasst ihn länger köcheln, als Ihr glaubt, dass er braucht, und dann noch einmal länger. Ein überstürzter Eintopf ist eine Suppe, die gelogen hat. Heute stehen die Höfe leer, und den Eintopf kochen die Leute, die sie verloren haben, in Lagern an der Straße zur Späherkuppe. Er ist nicht verfeinert. Er ist ehrlich, und in Westfall ist das heute seltener als Verfeinerung." },
    [2544] = { "Jeder Lehrer lehrt Krebsküchlein, und jeder Lehrer lehrt sie zu nass. Kriecherfleisch, sauber ausgelöst, eine Prise milder Gewürze, mit den Händen zusammengedrückt und mit sonst nichts, dann gebraten, bis die Außenseite zu einer Kruste wird, die den Rest zusammenhält. Fällt es auseinander, habt Ihr zu wenig gedrückt. Springt es zurück, habt Ihr zu viel gedrückt. Ein Krebsküchlein soll fest sein, wie ein Händedruck fest ist, und nicht fester." },
    [2545] = { "Die Küste von Westfall wimmelt von Krebsen, und die Schmuggler der Defias, die sich dort verstecken, haben, wie man mir sagt, mein Rezept für ihre Scheren gestohlen. Ich fühle mich geschmeichelt. Eine Schere sollte geknackt werden, bevor sie das Feuer trifft, damit die Hitze das Fleisch im Inneren erreicht, statt es in seiner eigenen Rüstung zu dämpfen. Eine Prise milder Gewürze in den Riss. Ein kurzes, heißes Feuer. Dann pult es mit einer Gabel heraus und denkt daran, dass selbst Diebe gut essen, wenn sie beim Richtigen stehlen." },
    [2546] = { "Trockene Rippchen sind ein Bauerngericht, die Rippchen eines Ebers und eine Würzmischung, ganz ohne Soße. Manche Köche fürchten sich davor. Sie glauben, eine Rippe müsse triefen, um gut zu sein. Eine Rippe muss gegart sein, um gut zu sein. Reibt die Gewürze am Abend vorher ein, lasst das Feuer zu einer schwachen Glut herunterbrennen und gebt den Rippchen den ganzen Nachmittag. Sie kommen dunkel, knusprig und trocken heraus, und sie lassen nichts am Knochen." },
    [2547] = { "Rotkammgulasch ist Spinne und Kondor, zusammen geschmort von den Leuten in Seenhain, die Spinnen und Kondore übrig haben, seit die Gnolle den Rest genommen haben. Die beiden Fleischsorten garen unterschiedlich schnell. Gebt den Kondor zuerst hinein, weil er zäh ist, und die Spinne später, weil sie es nicht ist. Von Anfang an zusammen gekocht, bekommt Ihr ein Fleisch verdorben und das andere roh. Ich verkaufe das Rezept mit dieser Warnung am Rand, in meiner eigenen Handschrift." },
    [2548] = { "Die Gnolle des Rotkammgebirges tragen dieses Rezept in ihren Bündeln umher, gestohlen aus irgendeinem Bauernhaus, und tun nichts damit. Ich verkaufe dasselbe Rezept in Sturmwind und tue sehr viel damit. Zwei Reihen Eberrippchen und scharfe Gewürze, und das ganze Geheimnis ist das Wenden. Wendet sie alle paar Minuten, damit das Fett das Fleisch begießt, während es schmilzt. Saftig ist kein Versprechen im Namen. Es ist der Lohn für Aufmerksamkeit." },
    [2549] = { "Dies ist das Gericht, unter das ich meinen Namen setzen würde, und ich habe es getan. Magere Wolfflanke und Würzkräuter aus Stormwind, sonst nichts, und wer Euch einen Ersatz für die Kräuter anbietet, will Euch etwas verkaufen. Lasst eine Lücke zwischen den Stücken auf dem Spieß, damit die Hitze jede Seite erreicht. Lasst ihn ruhen, bevor Ihr ihn esst. Ein Kebab, der überstürzt vom Feuer genommen wird, weint auf dem Teller, und Ihr mit ihm." },
    [2795] = { "Ragnar Donnerbräu glaubt, dieses Rezept gehöre seiner Familie. Ich verkaufe es in Sturmwind zu einem fairen Preis, und ich habe es verbessert. Er wird Euch sagen, die Rippchen bräuchten Rhapsody-Malzbier von der ersten bis zur letzten Minute. Das tun sie nicht. Die Zwerge begießen von Anfang an und wundern sich dann, warum die Außenseite verbrennt, während das Innere schmollt. Röstet die Rippe blank, bis das Fett klar läuft, und beginnt erst dann mit dem Malzbier, immer ein wenig, damit es zu einer Glasur wird statt zu Kohle. Das Ergebnis ist süß, dunkel und klebrig, und es ist das Feinste, was je aus Dun Morogh kam. Ich würde es Ragnar sagen, wenn er über den Lärm seiner eigenen Taverne hinweg irgendetwas hören könnte. Ich vermute, er weiß es. Seine Rippchen sind seitdem besser geworden." },
    [3370] = { "Krokilisk ist das Steak für jene, die Rind für zu gefällig halten. Das Sumpfland ist voll von ihnen, und die Jäger von Menethil bringen mir die Schwänze in Fässern voller Salzlake. Das Fleisch ist blass und fest, näher am Fisch als am Tier. Gart es, wie Ihr einen dicken Fisch garen würdet: heiß, kurz und niemals zweimal. Aufgewärmter Krokilisk schmeckt nach dem Sumpf, aus dem er kam, und nach diesem Geschmack hat noch nie jemand gefragt." },
    [3371] = { "Die Zwerge von Thelsamar machen jeden Winter Blutwurst und schicken ein paar nach Ironforge, wo Daryl Riknussun sie laut lobt und seinen Schülern dann beibringt, sie schlechter zu machen. Ich verkaufe das Rezept hier, berichtigt. Bärenfleisch, gereinigte Ebergedärme und Spinnensekret, das bindet, wie es einst das Blut tat, und sich weit besser hält. Füllt die Hülle locker. Eine pralle Wurst platzt in der Pfanne und entleert sich in die Glut, und noch nie hat jemand eine Wurst geliebt, die aufgegeben hat." },
    [3372] = { "Murlocflossen ergeben eine Suppe mit mehr Körper, als Ihr glauben würdet, wenn Ihr Murlocs bisher nur am Ende eines Schwertes begegnet seid. Zwei Flossen und scharfe Gewürze, geköchelt, bis sich die Flossen in der Brühe auflösen und ihr eine Fülle wie der beste Knochenfond geben. Die Murlocs, vermute ich, hätten Einwände. Die Murlocs haben gegen alles Einwände, ausführlich, und keinen davon in einer Sprache, die ich lernen möchte." },
    [3373] = { "Gumbo ist ein Gericht der Sümpfe, ein dicker, dunkler Eintopf, den die Leute im Sumpfland kochen, als hinge ihr Leben davon ab, und im Sumpfland tut es das manchmal. Zartes Krokiliskenfleisch und scharfe Gewürze, eingekocht, bis die Brühe dunkel und dick genug ist, um einen Löffel zu überziehen. Die Farbe ist das Maß. Zu blass, und er wurde überstürzt. Zu dunkel, und Ihr habt den Boden des Topfes verbrannt und solltet mit Würde von vorn beginnen." },
    [3376] = { "Seltsam schmeckend ist der ehrlichste Name in meinem Verzeichnis, denn jeder, der es isst, fragt sich, warum es so gut ist. Es besteht aus einem Raptorei, das um einiges gehaltvoller ist als ein Hühnerei, und scharfen Gewürzen. Schlagt es kräftig, gart es schnell und klappt es weich zusammen. Ein Raptorei stockt langsamer als ein Hühnerei, also habt Geduld mit der Mitte. Die Verwunderung ist verdient. Das Omelett ist meines, kraft meiner Verbesserungen." },
    [3377] = { "Ich verkaufe ein Rezept namens klebriger Spinnenkuchen, und ich verkaufe es mit ernster Miene, denn er ist sehr gut. Zwei klebrige Spinnenbeine, das Fleisch herausgelöst und mit scharfen Gewürzen vermengt, zu Küchlein gedrückt und gebraten, bis die Außenseite knusprig wird und das Innere weich bleibt. Das Klebrige steht im Namen und soll in der Mitte bleiben. Ein Kuchen, der ausläuft, wurde zu heiß gebraten. Die Leute im Dämmerwald essen sie dutzendweise, und das ist das Mutigste, was ich über den Dämmerwald weiß." },
    [3397] = { "Die Bären von Ashenvale werden größer als unsere, genährt von der Geduld der Nachtelfen und von dem, was sie unter den Bäumen finden. Ihr Fleisch ist dunkel und reichhaltig und will scharfe Gewürze, die es durchschneiden. Bratet es scharf an und lasst es lange ruhen, länger als bei einem kleineren Tier, denn ein großes Steak gart weiter, nachdem es das Feuer verlassen hat. In Desolace, so höre ich, verkauft eine Goblinmaschine meine Rezepte, ein Exemplar nach dem anderen. Ihren Koch würde ich gern kennenlernen." },
    [3398] = { "Löwen aus dem Brachland, in Koteletts geschnitten und mit scharfen Gewürzen verbrannt, von Köchen, die das Ergebnis eine Delikatesse nennen. Ich nenne es einen Löwen, der Besseres verdient hatte. Das Fleisch eines Löwen ist mager und süß nah am Knochen, und darum sollte das Kotelett am Knochen gegart werden. Scharfe Gewürze sind willkommen. Scharfes Feuer nicht. Gebt den Koteletts mäßige Hitze und wendet sie oft. Ein Löwe sollte so auf den Tisch kommen, als hätte er einen fairen Kampf verloren." },
    [3399] = { "Schmackhaft nennt es sich, und es ist um die Hälfte zu bescheiden. Zwei Stücke Löwe und feine Gewürze, als Steak gegart statt gehackt, und das ist die einzige zivilisierte Art, einen Löwen zu essen. Die feinen Gewürze sind nicht dazu da, den Koch zu beruhigen. Sie runden die Süße des Fleisches ab. Bratet es an, lasst es ruhen, schneidet es quer zur Faser. Ein Löwensteak, längs der Faser geschnitten, kaut sich wie ein Streit, den man nicht gewinnen kann." },
    [3400] = { "Eine Cremesuppe ist eine glatte Suppe, und die Schildkrötensuppe ist glatt, weil die Schildkröte alles hergegeben hat, was sie zu geben hatte. Schildkrötenfleisch und feine Gewürze, stundenlang geköchelt und dann durch ein Sieb gestrichen, bis nichts mehr bleibt, woran ein Löffel hängen bleiben könnte. Das Sieb ist das Rezept. Lasst es weg, und Ihr habt einen Schildkrötentopf, und das ist etwas anderes und Geringeres. Mild nennt sie sich. Ich würde sagen, geduldig, und ich hätte recht." },
    [4094] = { "Im Ödland wird man Euch sagen, ein Bussard sei die Kohlen nicht wert. Sie haben ihn nie gegrillt gegessen. Ein Bussardflügel ist größtenteils Sehne und Bosheit, also will er scharfe Gewürze und eine lange, niedrige Hitze, dann am Ende eine kurze, heftige, damit die Haut Blasen wirft. Die Jäger von Arathi verkaufen das Rezept für einen Spottpreis, was ein Verbrechen an der Kochkunst ist, und ich habe es niemandem gemeldet." },
    [6412] = { "Die Nachtelfen von Teldrassil lehren Euch diesen Kebab für den Preis von ein paar Spinnenbeinen, was Euch verrät, was sie von Spinnen halten. Alegorn in Darnassus würde Euch jedes Bein mit einem Zweig von irgendetwas Grünem aufspießen und die Spieße wie ein Gedicht anordnen lassen. Vergesst das Gedicht. Spinnenbeine wollen eine heftige, kurze Hitze, genug, um die Schale aufzubrechen, und nicht mehr, sonst wird das Fleisch darin zu Bindfaden. Danach dürft Ihr garnieren, wenn es sein muss. Bei mir muss es nie sein." },
    [6413] = { "Ein Gericht der Horde, aus dem Staub von Durotar, und die Überraschung ist, dass irgendjemand absichtlich einen Skorpid isst. Ich habe es nicht nötig, die Küche von Orgrimmar zu kosten. Ich habe jedoch das Rezept gelesen, denn ein Meister liest alles. Seine einzige Weisheit ist der Stachel. Gegart, bis er von Glas zu Kreide wird, verliert er sein Gift und behält seinen Biss. Zu kurz gegart, behält er beides. Ich überlasse es Euch, welches davon Ihr eine Überraschung nennen wollt." },
    [6414] = { "Kodo ist das Fleisch von Mulgore, dort von Tauren geröstet, die unter offenem Himmel kochen, mit der Ebene als Küche. Ich habe nie unter diesem Himmel gestanden, und ich habe es auch nicht vor. Ein Kodo ist ein gewaltiges, geduldiges Tier, und sein Fleisch ist ebenfalls geduldig: zuerst zäh, am Ende großzügig. Röstet es langsam und lasst es so lange ruhen, wie es geröstet hat. In einem haben die Tauren recht, und zwar darin: Manches Fleisch lässt sich von niemandem drängen." },
    [6415] = { "Die Frenzys der Dunkelküste sind nichts als Zähne und Temperament, und die Nachtelfen filetieren sie mit einer Andacht, die ich übertrieben finde. Alegorn würde Euch das Filet auf ein Blatt legen und etwas darüber murmeln lassen. Ich würde es Euch leicht würzen und schnell braten lassen, denn Frenzyfleisch ist weich und zerfällt, wenn man es auch nur langsam ansieht. Hautseite nach unten, eine heiße Pfanne, einmal wenden. Das Blatt ist freiwillig. Das Murmeln geht mich nichts an." },
    [6416] = { "Der Schreiter ist der langbeinige Vogel des Brachlands, nichts als Hals und Meinung, und die Horde schmort ihn mit Äpfeln, und das ist das erste Vernünftige, was ich je von ihr gehört habe. Der Apfel süßt die Brühe und macht das Fleisch weich, und das Fleisch hat es nötig. Lasst ihn langsam köcheln, bis der Apfel sich in nichts aufgelöst und der Vogel seine Sturheit aufgegeben hat. Ich würde dafür nicht übers Meer fahren. Ich würde ihn aber auch nicht ablehnen." },
    [6417] = { "Ein Eintopf aus Ratten, gelehrt von der Horde im Brachland, jedem, der die Ratten für sie fängt. Ich nehme ihn auf, weil ich gründlich bin, nicht weil ich ihn empfehle. Eine Grubenratte ist klein und mager und, wie man mir sagt, sauberer als die Ratten unserer eigenen Kanäle, und das ist ein schwaches Lob. Schmort sie lange. Alles an diesem Gericht deutet auf langes Kochen hin, auch das Bedürfnis des Kochs, zu vergessen, was im Topf ist." },
    [6418] = { "Ein Gericht aus dem Brachland, in Crossroads verkauft und von der Horde mit den Fingern gegessen. Die Finger erwähne ich nur, damit Ihr es ihnen nicht nachmacht. Der Schwanz einer Donnerechse ist reiner Muskel, und das Knusprige kommt daher, dass man ihn in seinem eigenen Fett gart, bis die Haut zersplittert. Scharfe Gewürze, eine heiße Pfanne und ein Koch, der mutig genug ist, ihn dort zu lassen. Ich werde nicht so tun, als bewunderte ich das Brachland. Ich gebe zu, dass der Schwanz gut erdacht ist." },
    [6419] = { "Wildbret ist das Fleisch eines Kochs mit guten Manieren. Ein Hirsch ist mager und stolz und muss entsprechend behandelt werden, mit reichlich eingeriebenen Gewürzen und sehr wenig Zeit auf dem Feuer. Gart einen Hirsch zu lange, und Ihr habt den Wald beleidigt. Die Elfen von Ashenvale verkaufen dieses Rezept, was mich rührt, da sie einen so großen Teil ihres Lebens damit verbringen, jeden von der Jagd auf ihre Hirsche abzuhalten. Gart es blutig, schneidet es dünn und sagt nichts darüber, woher es kam." },
    [6499] = { "Eine Muschel ist ein Mundvoll Meer, und der einzige Weg, sie zu verderben, ist, sie im Topf zu vergessen, und genau das tut jeder. Die Seeleute am Hafen kochen sie in Meerwasser und nennen es Tradition. Ich nenne es Faulheit mit Aussicht. Nehmt gutes Quellwasser, zählt langsam bis sechzig und holt sie heraus. Gummi ist für Stiefel. Wenn Ihr das Bedürfnis nach einer Soße verspürt, habt Ihr sie zu lange gekocht." },
    [6500] = { "Die Goblins machen ihre Muscheln scharf, wie sie Geschäfte machen: mit zu viel Hitze und einer Menge Lärm. Ich lehre das Rezept trotzdem, mit berichtigter Hitze. Würziges Muschelfleisch, scharfe Gewürze und ein Feuer, das heiß ist, aber nicht wütend. Eine wütend gekochte Muschel wird zu Leder. Eine gut gekochte Muschel hat gerade noch genug Kampfgeist, um Euch daran zu erinnern, dass sie aus dem Meer kam. Die Goblins würden Euch für das Leder das Doppelte berechnen." },
    [6501] = { "Muschelsuppe ist Muscheln und Milch, und die Milch darf niemals kochen. Das ist die ganze Schwierigkeit, und sie genügt, um die meisten Köche an der Küste zu besiegen. Erwärmt die Milch sanft, gebt das Muschelfleisch und eine Prise milder Gewürze hinzu und haltet sie unter dem Köcheln, bis die Muscheln eben gar sind. Gekochte Milch gerinnt, und geronnene Muschelsuppe sieht aus wie ein Fehler in einer Schüssel. Die Fischersfrauen von Westfall machen es öfter richtig als die Gasthäuser. Die Gasthäuser sollten sich schämen." },
    [7213] = { "Die Köche von Booty Bay rösten eine Riesenmuschel in scharfen Gewürzen und servieren sie Piraten, die alles essen würden, was nicht zurückbeißt, und einiges, was es tut. Ich habe es verfeinert. Riesenmuschelfleisch ist dicht und süß, und der Kniff ist, es in dünne Scheiben zu schneiden, bevor die Hitze es berührt, damit die Gewürze hindurchdringen. Dann Feuer, heftig und schnell. Dieses Gericht soll dem Koch die Augenbrauen versengen und die Muschel verschonen." },
    [7751] = { "Der erste Fisch jedes Kindes mit einer Angel, und der erste Fisch, über den viele Köche nie hinauskommen. Ein Kleinfisch ist ein Mundvoll, und ein Mundvoll verzeiht nichts. Bratet ihn im Ganzen in einer heißen Pfanne, und nur, bis sich das Auge trübt. Das ist Eure Uhr, und der Fisch trägt sie für Euch. Die Fischer am Hafen verkaufen diese eimerweise an Kinder, die sie verbrennen. Ich verkaufe sie nicht. Ich berichtige sie." },
    [7752] = { "Die Makrele ist ein öliger Fisch, und Öl ist ein Geschenk, das die meisten Köche wie ein Problem behandeln. Sie ertränken es, sie kratzen es ab, sie entschuldigen sich dafür. Legt sie mit der Haut nach unten in eine trockene, heiße Pfanne und lasst ihr eigenes Öl sie garen. Die Haut wird knusprig, das Fleisch bleibt süß, und die Küche riecht einen Tag lang nach Meer, was keine Strafe ist. Das habe ich als Junge an den Docks gelernt. Ich habe es nur ein wenig verbessert, und das ist aus meinem Mund ein Kompliment." },
    [7753] = { "Ein Schnapper vom schlammigen Grund träger Flüsse, und er schmeckt nach ihnen, wenn man es nicht besser weiß. Ich weiß es besser. Nehmt ihn gut aus, gart ihn im Ganzen über mäßigem Feuer und zieht vor dem Servieren die Haut ab. Der Schlamm steckt in der Haut, nicht im Fleisch. Die Fischer essen ihn mit Haut und allem und erzählen Euch, der Fluss gehöre zum Reiz. Der Fluss gehört zum Fluss. Lasst ihn dort." },
    [7754] = { "Die Zwerge von Loch Modan haben dieses Gericht ein Supreme genannt, und das ist das großzügigste Wort, das ich je einen Zwerg über etwas ohne Malz darin habe sagen hören. Der Frenzy von dort ist fester als seine Vettern im Süden, Fleisch aus kaltem Wasser, das in der Pfanne zusammenhält. Würzt ihn mit milden Gewürzen, bratet ihn schnell und serviert ihn heiß. Den Namen gestehe ich den Zwergen zu. Die Methode nicht, denn zu ihr gehört eine Menge Geschrei." },
    [7755] = { "Der Wels ist ein Flussfisch, breitmäulig und bärtig und allgemein verachtet von Leuten, die ihn nie richtig zubereitet haben. Zieht ihm die Haut ab, immer. Die Haut eines Welses schmeckt nach Flussbett, und Flussbett ist kein Geschmack. Das Fleisch darunter ist weiß und süß und verträgt sich gut mit einer heißen Pfanne und einem schnellen Wenden. Die Fischer an den Flüssen von Hillsbrad schwören darauf. Ausnahmsweise sind die Fischer und ich einer Meinung." },
    [7827] = { "Der Thunfisch ist ein Fisch für Leute, die finden, ein Fisch solle sich wie Fleisch benehmen. Er ist fest, dunkel und reichhaltig, und er verträgt ein scharfes Anbraten außen und sehr wenig Garen in der Mitte. Die Seeleute von Menethil braten ihn durch, bis er grau ist, und geben dem Fisch die Schuld. Ich verkaufe kein Rezept dafür, aber ich würde es tun, und ich würde mehr verlangen. Rosa in der Mitte ist richtig. Grau ist ein Geständnis." },
    [7828] = { "Der Kabeljau ist der Fisch kalter Meere und ehrlicher Küchen, und der Steinschuppenkabeljau ist der beste von ihnen, so genannt, weil seine Schuppen ein billiges Messer stumpf machen würden. Schuppt ihn, bevor Ihr irgendetwas anderes tut, mit einer guten Klinge und etwas Geduld. Dann eine heiße Pfanne und ein einziges Wenden. Das Fleisch ist weiß und zerfällt in große, saubere Flocken, und es braucht nichts, nicht einmal eine Meinung. Ich gebe ihm trotzdem eine. Ausgezeichnet." },
    [8238] = { "Deviatfische kommen aus den vergifteten Becken der Höhlen des Wehklagens im Brachland, und ich hatte nie den geringsten Wunsch, einen zu holen. Das Rezept findet man in den Bäuchen der Kodos, die dort umherziehen, und das sagt Euch, was die Kodos davon halten. Gart ihn durch, mit milden Gewürzen, und esst ihn auf eigene Gefahr. Man sagt mir, er habe für jene, die ihn essen, seltsame Folgen. Man sagt mir sehr vieles über das Brachland." },
    [8604] = { "Jeder Koch in dieser Stadt glaubt, er könne ein Ei backen. Die meisten irren sich, und zwar alle auf dieselbe Weise: zu heiß, zu lange und in Eile, es hinter sich zu bringen. Es ist das erste Gericht, das ich lehre, und das, an dem ich einen Koch messe. Würzt das Eiweiß, niemals den Dotter. Der Dotter ist bereits vollkommen und legt keinen Wert auf Eure Meinung. Tomas in Goldhain bereitet ein durchaus achtbares zu. Ich habe es ihm beigebracht." },
    [8607] = { "Das Räuchern ist die Kunst der Zwerge, und ich sage das ohne Vergnügen. In Loch Modan hängen sie Bärenfleisch in den Rauch ihrer Kamine und vergessen es dort den ganzen Winter über, und im Frühling ist es besser als alles, was sie zu kochen vorhatten. Das Geheimnis ist der Abstand. Das Fleisch hängt hoch, wo die Hitze es nie erreicht und nur der Rauch die Arbeit tut. Nah am Feuer röstet Ihr schlecht. Fern davon räuchert Ihr gut." },
    [9513] = { "Disteltee ist das Getränk der Schurken dieses Königreichs, die ihn aus Flitzdistel und Quellwasser brauen und trinken, bevor sie tun, was immer Schurken tun. Ich frage nicht. Lasst die Flitzdistel in Wasser ziehen, das gerade nicht mehr kocht, bis es grüngolden wird, und seiht sie dann ab. Zu lange gezogene Flitzdistel wird bitter, und das, so sagt man mir, ziehen Schurken vor. Ich ziehe es vor zu wissen, wo mein Geldbeutel ist, wenn sie ihn trinken." },
    [13028] = { "Golddorn wächst an den harten Orten, im Schlingendorntal und im Hinterland, und er ergibt einen Tee, den jeder Lehrer lehrt und jeder Soldat bei sich trägt. Ein Golddorn ergibt vier Tassen, was Euch sagt, wie kräftig er ist. Lasst ihn in Wasser ziehen, das gerade nicht mehr kocht, bis das Wasser die Farbe von altem Messing hat, und seiht ihn dann gründlich ab. Ein Golddorn, der in der Tasse bleibt, macht den Tee so bitter, dass er Farbe abbeizt. Ich habe es gesehen. Die Farbe hat sich nicht erholt." },
    [15853] = { "Ein schlichtes Steak aus der Flanke eines Wolfs, und das Schlichte ist am schwersten zu kochen. Es gibt keine Soße, hinter der man sich verstecken, und keinen Eintopf, in dem man einen Fehler begraben kann. Die Flanke ist mager, also muss sie schnell angebraten und lange ruhen gelassen werden, mit ein wenig Gewürz, das sie daran erinnert, dass sie Essen ist. Blutig ist richtig. Medium ist verzeihlich. Alles darüber hinaus, und ich empfehle ein anderes Handwerk, und ich kenne mehrere, die gar kein Feuer brauchen." },
    [15855] = { "Gerösteter Raptor ist Soldatenessen, verkauft in den Lagern im Schlingendorntal, wo Männer essen, was versucht hat, sie zu essen. Das ist Grund genug, ihn zu achten. Raptorfleisch ist mager und schnell gar, also röstet es am besten in großen Stücken, die ihre eigene Mitte schützen. Scharfe Gewürze außen, ein kräftiges Feuer, und dann weg von der Hitze, damit er fertig gart. Ein Raptor, geröstet wie ein Huhn, kommt heraus wie ein Stiefel. Ein Raptor, geröstet wie ein Raptor, kommt heraus wie ein Sieg." },
    [15856] = { "Die Wölfe des fernen Südens sind rot, übellaunig und größer als unsere, und ihre Rippen kommen mit viel Fleisch daran. In Feralas verkauft man dieses Rezept jedem, der durchreist, und das tun wenige. Scharfe Gewürze, ein heißes Feuer und dann Geduld, denn roter Wolf ist fetter als unsere graue Sorte und braucht Zeit, bis das Fett schmilzt. Wenn das Fett klar läuft und die Knochen dunkel werden, sind sie fertig. Wenn das Fett raucht, ist auch Euer Ruf dahin." },
    [15861] = { "Ein Eintopf aus dem Schlingendorntal, gemacht von Soldaten, die Tigerfleisch, Quellwasser und Äpfel hatten, und den Verstand, sie zusammenzubringen. Die Äpfel süßen, was sonst eine harte, nach Wild schmeckende Brühe wäre. Bräunt zuerst den Tiger, gebt dann das Wasser und die Äpfel hinzu und lasst ihn köcheln, bis die Frucht im Eintopf verschwunden ist. Ein Dschungel bringt sehr viel Essen hervor und sehr wenige Rezepte. Dies ist eines der guten." },
    [15863] = { "Aas Surprise. Ich habe das Rezept zweimal gelesen, für den Fall, dass der Name ein Scherz war. Er ist es nicht. Eigenartiges Fleisch und scharfe Gewürze, zu einem Gericht gekocht, das die Trolle in den Sümpfen des Elends verkaufen, als wäre es eine Wohltat. Das Fleisch muss durchgegart werden und dann noch einmal durchgegart, denn was immer es einst war, es ist schon eine Weile tot. Ich serviere es nicht. Ich lehre es, damit meine Schüler wissen, was sie meiden." },
    [15865] = { "Der eigenartige Eintopf ist eigenartiges Fleisch, in zwergischem Starkbier geschmort, und das Eigenartige ist, wer von beiden mehr Arbeit leistet. Ich sage es Euch: das Starkbier. Ein Schlauch gutes zwergisches Starkbier macht das Fleisch dunkel und weich und gibt der Brühe eine Bitterkeit, die eine Vielzahl von Sünden verbirgt. Daryl Riknussun lehrt dies in Ironforge als zwergisches Gericht, was großzügig von ihm ist, da die Zwerge nur das Bier und die Fragen beigesteuert haben. Kocht ihn lange. Was immer das Fleisch einst war, es muss es vergessen. Schöpft den Schaum ab, während er köchelt, und lasst ihn niemals kochen, sonst wird das Starkbier sauer und das Fleisch zu Bindfaden. In Theramore und Desolace wird er Leuten serviert, die aufgehört haben, Fragen zu stellen, und er ist, das gebe ich zu, sehr gut. Auch ich habe aufgehört, Fragen zu stellen. Es war leichter, als ich erwartet hatte." },
    [15906] = { "Man sagt mir, dieses Gericht habe als Mutprobe in irgendeiner Taverne begonnen, in der zu trinken niemand zugibt. Es ist seiner Herkunft entwachsen, wie ich. Die meisten Köche behandeln es als Wettkampf und kochen es als Waffe, und das sagt mehr über die Köche als über das Chili. Eigenartiges Fleisch ist ein Name, keine Ausrede. Putzt es, als hätte es einen Ruf zu verlieren. Röstet die Gewürze, bevor irgendetwas anderes sie berührt, damit sie aufwachen. Der kleine Flammenbeutel kommt zuletzt hinein, einmal angestochen, und Ihr tretet weit zurück. Ihr werdet verstehen, warum, an dem Tag, an dem Ihr es falsch macht. Richtig gemacht, kommt die Schärfe spät und geht langsam, wie ein guter Gast. Schlecht gemacht, kommt sie zuerst und bleibt den ganzen Abend, und die Nachtwache darf es gern behalten." },
    [15910] = { "Die Kodos von Desolace werden schwerer als die des Brachlands, obwohl sie von gar nichts leben, und ihr Fleisch ist das dichteste, das ich kenne. Ich habe es nicht nötig, die Küche der Horde zu kosten, und ich mache eine Ausnahme für diesen Eintopf, weil er weniger Horde ist als Kodo, und der Kodo ist ohne Schuld. Zwei Portionen schweres Kodofleisch, feine Gewürze und Quellwasser, und ein ganzer Tag über kleinem Feuer. Das Fleisch kommt kalt hinein und in Fäden wieder heraus. Überstürzt es nicht, und hebt nicht jede Stunde den Deckel, um nachzusehen, wie es ihm geht. Es tut, was Kodo tut: Es lässt sich Zeit. In Desolace verkauft man dieses Rezept in Sichtweite der Kodoknochen, die das Tal übersäen, was mir ein wenig taktlos scheint, und durch und durch praktisch." },
    [15915] = { "Chilikrebs ist ein Gericht des heißen Südens, wo die Köche glauben, Schärfe sei eine Form der Gastfreundschaft. Zartes Krebsfleisch, eine Menge scharfer Gewürze und eine Pfanne, so heiß, dass Ihr einen Schritt zurücktretet. Der Krebs muss in den Gewürzen garen, nicht unter ihnen, also rührt unablässig. Er ist unordentlich zu essen und unmöglich höflich zu essen. Ich serviere ihn mit einer Warnung und einer großen Serviette, und die Serviette behalte ich." },
    [15933] = { "Ein Monsteromelett wird aus einem einzigen Riesenei gemacht, und ein einziges Riesenei genügt, um einen Tisch mit sechs Gästen satt zu machen, oder einen Orc. Die Eier stammen von den großen Vögeln des Nordens und werden im Teufelswald und in Winterspring von Leuten verkauft, die gelernt haben, nicht zu fragen, wo sie gesammelt wurden. Schlagt das Ei mit feinen Gewürzen, bis es glatt und blass ist, und gart es dann in der breitesten Pfanne, die Ihr besitzt, bei mittlerer Hitze, und zieht die Ränder ein, sobald sie stocken. Die Versuchung ist groß, es zu überstürzen, denn es ist gewaltig und die Gäste sehen zu. Widersteht ihr. Ein zu schnell gegartes Monsteromelett ist außen braun und innen roh, und das verzeiht niemand. Klappt es zusammen, wenn die Oberfläche gerade eben gestockt ist, und lasst die Hitze die Mitte auf dem Weg zum Tisch vollenden. Dann tragt es mit beiden Händen hinein und genießt die Stille." },
    [15935] = { "Dieses Rezept stammt aus Tirisfal, wo die Köche tot sind und die Fledermäuse noch nicht. Es erreichte mich über einen Händler, dem ich mehr traue als seiner Ware. So viel gestehe ich ihm zu: Ein Flügel ist größtenteils Haut, und Haut belohnt einen Koch, der sie in Ruhe lässt. Legt ihn mit der Haut nach unten auf ein heißes Eisen und rührt ihn nicht an, bis er sich von selbst von der Pfanne löst. Das ist die ganze Kunst. Den Rest der Küche von Tirisfal überlasse ich Tirisfal." },
    [18238] = { "Gelbschwanz aus den warmen Gewässern vor Tanaris, verkauft von einem Goblin, der seinen Fisch mit der einen Hand wiegt und den Kunden mit der anderen. Der Fisch ist trotzdem hervorragend. Er ist fest und ölig und braucht nur eine heiße Pfanne und ein einziges Wenden. Macht kein Aufhebens um ihn. Der Tüpfelgelbschwanz ist der seltene Fisch, der umso besser wird, je weniger ein Koch tut, und viele Köche finden das unerträglich." },
    [18239] = { "Ein großer, glänzender Fisch aus den warmen Gewässern des Südens, reichhaltig genug, um in dicken Steaks serviert zu werden. Feine Gewürze stehen ihm gut, sie runden die Fülle ab, statt gegen sie zu kämpfen. Bratet die Steaks scharf an und lasst sie ruhen, wie Ihr es mit Fleisch tun würdet. Die Seeleute von Booty Bay garen ihn in großen Stücken über Treibholz und essen ihn mit ihren Messern. Ich habe es gesehen. Ich sehe es manchmal noch, in manchen Nächten." },
    [18240] = { "Kalmar gart man entweder einen Augenblick oder eine Stunde, und alles dazwischen ist Gummi. Ich ziehe den Augenblick vor. Ritzt den Körper kreuzweise ein, reibt ein wenig feine Gewürze hinein und legt ihn auf den heißesten Grill, den Ihr besitzt, so lange, wie es dauert, seinen Namen zweimal zu sagen. Er rollt sich ein, er verkohlt an den Rändern, er ist fertig. Die Köche des Südens geben ihm eine Stunde im Eintopf. Sie irren sich, aber auf interessante Weise." },
    [18241] = { "Die Rotkieme ist ein Küstenfisch, benannt nach dem roten Schimmer an ihren Kiemen, der verblasst, sobald sie gefangen und gegart ist, wie es den meisten Dingen geht. Sie braucht nichts. Ein Filet, eine heiße Pfanne, die Hautseite nach unten, bis es sich von selbst löst. Ich habe Köche bei diesem Fisch aus lauter Nervosität nach jedem Gewürz im Regal greifen sehen. Eine gute Rotkieme ist kein Problem, das gelöst werden muss. Sie ist ein Fisch, den man in Ruhe lässt." },
    [18242] = { "Heißräuchern ist Räuchern bei einer Hitze, die zugleich gart, und das geht schneller als das kalte Räuchern und verzeiht weniger. Reibt den Sommerbarsch mit scharfen Gewürzen ein, hängt ihn dicht über ein rauchiges Feuer und behaltet ihn im Auge. Wenn das Fleisch von glasig zu weiß wechselt, ist er fertig. So geräucherter Barsch hält sich tagelang und reist gut. Es ist der einzige Fisch, den ich dem Gepäck eines Soldaten anvertrauen würde, und ich habe ihn mehreren anvertraut." },
    [18243] = { "Der Nachtflossenschnapper wird nach Einbruch der Dunkelheit gefangen, und so erklären die Fischer ihre Arbeitszeiten und ihre Launen. Die Suppe ist der Fisch und Quellwasser, sonst nichts, und das ist genau genug. Lasst den Schnapper sanft köcheln, bis das Fleisch von den Gräten fällt, und hebt dann die Gräten heraus. Die Brühe sollte klar genug sein, um hindurchzulesen. Trübt sie sich, habt Ihr sie gekocht. Ist sie klar, dürft Ihr mir Eure Entschuldigung später vorlesen." },
    [18244] = { "Pochieren ist die Kunst, in Wasser zu garen, das nie ganz kocht, und es ist die am meisten unterschätzte Kunst jeder Küche. Der Sonnenschuppenlachs aus den warmen Meeren ist reichhaltig und weich und würde unter einer härteren Methode zerfallen. Bringt das Wasser zum Zittern, nicht zum Kochen, lasst den Fisch hinein und lasst ihn in Ruhe. Wenn er undurchsichtig wird, hebt ihn heraus. Das Wasser sollte nicht ein einziges Mal die Stimme erhoben haben." },
    [18245] = { "Dunkelklauenhummer von den kalten Küsten des Nordens, in Quellwasser geschmort und in sonst nichts. Ein Hummer braucht keine Hilfe, nur Achtung. Bringt das Wasser zum Köcheln, lasst den Hummer im Ganzen hinein und hebt ihn heraus, sobald die Schale rot wird. Dann löst das Fleisch aus der Schale und gebt es zum Erwärmen in die Brühe zurück. Ein zweimal gekochter Hummer ist eine Beleidigung. Ein zweimal erwärmter Hummer ist ein Eintopf." },
    [18246] = { "Ein Machtfisch ist groß genug, um wie ein Stier in Steaks geschnitten zu werden, und man sollte ihn auch wie einen behandeln. Zweierlei Gewürze, scharfe und feine, die einen, um das Fleisch zu wecken, die anderen, um es zu beruhigen. Bratet die Steaks auf beiden Seiten scharf an und lasst sie vor dem Servieren ruhen. Die Fischer des fernen Südens holen sie mit Netzen und viel Geschrei herein. Ich ziehe sie auf dem Teller vor, in Stille, mit dem Beifall danach." },
    [18247] = { "Weißschuppenlachs aus den kalten Flüssen, im Ganzen mit feinen Gewürzen in einem mäßigen Ofen gebacken. Ein ganzer Fisch backt gleichmäßig, wo ein Filet an den Rändern austrocknet, und die Haut schützt das Fleisch wie ein Deckel. Wenn das Auge weiß wird und die Flosse sich mühelos löst, ist er fertig. In Feralas verkauft man dieses Rezept an die wenigen, die so weit kommen. Sie verdienen es, schon allein für die Reise." },
    [20626] = { "Eine Muschelsuppe der Goblins, in Tanaris verkauft von einem Goblin namens Jabbey, der immer nur ein Exemplar vorrätig hat und die Knappheit mehr genießt als die Suppe. Die Suppe ist besser als der Goblin. Scharfes Muschelfleisch, scharfe Gewürze und eiskalte Milch, zusammen erwärmt, ohne je zu kochen. Die Goblins von Undermine essen sie angeblich kochend heiß. Ich empfehle, sie bei einer Temperatur zu essen, die keinen Heiler erfordert." },
    [20916] = { "Eine Forelle mit einem silbrigen Kopf von der Farbe des Mithrils, was den Namen erklärt, und mit einem Temperament, das dazu passt, was die verbundenen Hände der Fischer erklärt. Sie ist ein Bergfisch und kaltblütig in jedem Sinne. Bratet sie im Ganzen, mit Haut, in einer heißen Pfanne und begießt sie mit ihrem eigenen Fett. Das Fleisch ist blass und fein. Der Kopf bleibt für den Tisch dran. Eine Forelle ohne Kopf sieht verlegen aus, und der Koch, der sie serviert hat, ebenso." },
    [21143] = { "Ein Gebäck zum Winterhauchfest, ein paar Wochen im Jahr von lächelnden Händlern in Rot verkauft und von Kindern gebacken, die die Hälfte davon essen, bevor es den Ofen erreicht. Die Festtagsgewürze sind das Ganze: warm, süß und scharf, und frisch müssen sie sein, denn alte Gewürze schmecken nach dem letzten Jahr. Ein Ei hält alles zusammen. Backt die Kuchen, bis die Ränder dunkel werden und die Mitte noch nachgibt. Beim Abkühlen werden sie fest. Ein Lebkuchen, der schon im Ofen hart wird, ist am Morgen eine Waffe." },
    [21144] = { "Eierflip ist das Getränk des Winterhauchs und der Grund, warum so viele Morgen des Winterhauchs spät beginnen. Ein Ei, eiskalte Milch, Festtagsgeister und Festtagsgewürze, zusammen geschlagen, bis alles blass und dick ist und riecht wie das Innere eines guten Schranks. Die Geister kommen zuletzt hinein, und in Maßen, was noch niemandem gelungen ist. Serviert ihn kalt, in kleinen Bechern, und füllt niemandem nach, der zu singen begonnen hat." },
    [21175] = { "Weißes Spinnenfleisch, zu einer Wurst gepresst und von jedem Kochkunstlehrer im Land gelehrt, als wäre es etwas Gewöhnliches. Es ist nicht gewöhnlich. Spinnenfleisch ist süß und zart, näher am Krebs als am Schwein, und es verlangt kein Gewürz, weil es keines braucht. Die Kunst ist die Hülle: fest genug, um zu halten, dünn genug, um in der Pfanne aufzuspringen. Viele Schüler erbleichen beim Wort Spinne. Ich frage sie, ob sie je einen Krebs gegessen haben, und warte." },
    [22480] = { "Zartes Wolfsfleisch kommt von den Wölfen aus Winterspring und den fernen kalten Orten, wo ein Tier langsam lebt und sein Fett behält. Es ist das beste Wolfsfleisch der Welt, und an die meisten Köche ist es verschwendet. Feine Gewürze, ein kurzes, heißes Anbraten, und dann lasst es so lange ruhen, wie Ihr es gegart habt. Ein Koch, der hundert sehnige Wölfe im Wald von Elwynn verdorben hat, wird bei diesem endlich verstehen, wonach er all die Zeit gegriffen hat." },
    [22761] = { "Das Rezept für dieses Gericht trägt ein Wichtel in den Ruinen von Düsterbruch bei sich, der es erst herausgibt, wenn er Euch auf eine lustige Hetzjagd durch Hallen voller sehr wütender Satyrn geführt hat. Ich weiß das, weil ein Schüler von mir diese Jagd gemacht hat und mit dem Rezept zurückkam, mit einem Hinken und mit einer Meinung über Wichtel, die ich teile. Die Runn Tum Knolle wächst im Schatten dieser Ruinen und schmeckt, gut zubereitet, wie die beste Wurzel, von der Ihr nie wusstet, dass es sie gibt: erdig, süß und ein wenig rauchig. Schält sie, schneidet sie in dicke Scheiben und röstet sie langsam mit feinen Gewürzen, bis die Ränder karamellisieren und die Mitte unter der Gabel nachgibt. Die Überraschung ist, dass etwas so Gutes von einem so schlimmen Ort kommt. Das Rezept lehre ich gern. Die Hetzjagd lehre ich nicht, und meinem Schüler habe ich geraten, sie niemals zu wiederholen." },
    [24418] = { "Schwer, sagt er, und das ist nicht gelogen: doppelt so viel Krokilisk, mit feinen Gewürzen, geschmort, bis ein Löffel darin steht. Die Soldaten von Theramore essen ihn aus Blechschüsseln im Regen der Marschen von Dustwallow und schwören, er sei das einzig Warme im ganzen Sumpf. Ich glaube ihnen. Einen so schweren Eintopf muss man oft vom Boden her umrühren, sonst setzt er an und verbrennt, wo Ihr es nicht sehen könnt. Die meisten verdorbenen Eintöpfe sterben am Boden des Topfes." },
    [24801] = { "Dieses Rezept wird nicht verkauft. Es wird gelehrt, von den Köchen des Zirkels des Cenarius in Silithus, an jene, die sich in einer Wüste bewährt haben, die ihnen nach dem Leben trachtet. Ich war nie in Silithus. Ich muss nicht dort gewesen sein, um zu wissen, dass Sandwurmfleisch eine Herausforderung ist: dicht, blass und mit Sand in jeder Falte. Wascht es, bis das Wasser klar abläuft, hackt es fein mit feinen Gewürzen und rollt es zu kleinen Knödeln, fest gedrückt, damit sie im Rauch zusammenhalten. Dann räuchert sie langsam über einem kleinen Feuer. Der Rauch würzt die Außenseite, der Dampf gart die Mitte, und wenn sie fertig sind, sind sie fest, duftend und vollkommen frei von Sand, was die eigentliche Leistung ist. Der Zirkel hütet dieses Rezept eifersüchtig, und ich achte ihn dafür. Ich habe Schlechteres für weniger gehütet." },
    [25659] = { "Dirge Quikcleave führt eine Küche in Gadgetzan, mitten in einer Wüste, wo er Chimaerok mit Goblin-Raketentreibstoff gart und sich das Vergnügen bezahlen lässt. Ich habe allen Grund, dieses Rezept zu verachten. Ich kann es nicht. Chimaeroklenden sind das feinste Fleisch auf Kalimdor, dicht und süß, von Tieren so weit entfernt, dass nur die Mutigen oder die Hungrigen es je zurückbringen. Tiefsteinsalz aus den Minen der Zwerge, scharfe Gewürze und der Treibstoff, der das Fleisch nicht so sehr würzt, als vielmehr dem Feuer zu einer Hitze schmeichelt, die keine ehrliche Kohle erreicht. Nehmt sehr viel Abstand und sehr wenig vom Treibstoff. Dirge würde Euch etwas anderes sagen. Dirge hat weniger Augenbrauen als ich. Die Koteletts kommen verkohlt und saftig heraus und sind, ich gebe es zu, das Beste, was je ein Goblin gemacht hat." },
    [25704] = { "Weisenfische kommen aus den Seen von Hillsbrad, wo das Wasser kalt und klar ist und die Fischer geduldig sind. Der Fisch nimmt den Duft des Salbeis an den Ufern an, und sanftes Räuchern hebt diesen Duft hervor. Wenig Rauch, eine Prise Gewürz und ein Nachmittag. Die Bauern von Southshore verkaufen ihn aus ihren Fenstern. Er ist das Beste in Southshore. Die Latte liegt dort niedrig, aber er nimmt sie mit Anstand." },
    [25954] = { "Der große Weisenfisch ist der erwachsene Weisenfisch, mit mehr von allem, auch vom Duft der Kräuter an seinem See. Scharfe Gewürze heben ihn hervor, ohne ihn zu begraben. Bratet das Filet mit der Haut nach unten, bis die Haut knusprig wird, und wendet es dann für einen Augenblick, nicht länger. Supreme ist ein starkes Wort für einen Fisch. Ich habe diesen gekostet, und ich nehme es nicht zurück." },
    [470359] = { "Eine Cremesuppe vom Dunkelklauenhummer, gemacht mit Weihwasser aus Stratholme, das, wie man mir sagt, trinkbar ist, obwohl ich das Etikett zweimal gelesen habe und noch immer nicht überzeugt bin. Die Expedition in Silithus verkauft sie, und ich vermute, sie haben sie erfunden, um das Weihwasser aufzubrauchen. Es funktioniert. Das Wasser ist sehr sauber und sehr weich, und es lässt den Hummer für sich selbst sprechen. Köcheln, sieben, und fragt nicht, wofür dieses Wasser sonst noch benutzt wurde." },
    [470370] = { "Ein Rezept, das in Silithus verkauft wird, von den Rüstmeistern der Expedition, an Soldaten, die Essen brauchten, das sich im Sand hält. Rotkieme, langsam geräuchert, bis sie trocken genug zum Reisen und noch zart genug zum Essen ist. Kein Gewürz, nur Rauch. Die Soldaten, die es nach Sturmwind zurückbrachten, baten mich, es gutzuheißen. Ich tat es, und das überraschte sie mehr als die Wüste." },
    [1225758] = { "Pirschersteak ist Tiger, nur ist der Name zu höflich, es zu sagen. Zwei Stücke davon, mit Weihsalz eingerieben und eine Stunde liegen gelassen, bevor das Feuer sie berührt. Tiger ist ein mageres, fleißiges Fleisch, und das Salz zähmt es. Der Rest ist Zurückhaltung: ein heißes Eisen, ein kurzes Anbraten und eine lange Ruhe. Ich habe Jäger behaupten hören, ein Tiger müsse zornig gegart werden. Jäger sollten jagen und die Küche jenen überlassen, die bis sechzig zählen können." },
    [1225759] = { "Filet aus der Flanke, ein bescheidener Name für ein Gericht, dem nichts fehlt. Die Flanke des roten Wolfs wird mit Weihsalz eingerieben, das, wie die Priesterschaft Euch sagen wird, gesegnet ist, und das, wie die Händler Euch sagen werden, teuer ist. Beide haben recht. Das Salz zieht das Wasser aus dem Fleisch und macht es fester, also gart es schnell. Ein gesegnetes Steak, das zu lange gegart wurde, ist trotzdem zu lange gegart. Das Licht wird es nicht retten, und ich auch nicht." },
    [1225760] = { "Ein Omelett aus zwei Rieseneiern, gewürzt mit Weihsalz, und irgendjemand hat es für einen Sonnenaufgang gehalten. Ich vermute, es liegt an der Farbe: ein sehr leuchtender Dotter, ein blasses Eiweiß und eine Prise Salz, das die Priesterschaft gesegnet und die Händler entsprechend bepreist haben. Gart es langsam, damit die Farbe leuchtend bleibt. Ein zu schnell gegarter Sonnenaufgang wird zum Mittag, und über den Mittag schreibt niemand Gedichte. Ich serviere es Priestern, die den Scherz zu schätzen wissen, und Paladinen, die es nicht tun." },
    [1225762] = { "Das Fleckfinnenfestmahl ist das Bankett eines Kochs, der sehr viel Fisch hatte und Ehrgeiz für genau einen Raptor. Zwölf Tüpfelgelbschwänze, drei Steinschuppenkabeljaue und vier Portionen Raptorfleisch, dazu erlesene Gewürze, die ihren Namen an der Ladentheke verdienen, wenn auch nicht immer in der Pfanne. Die Fische werden im Ganzen gegrillt und der Raptor gebraten, und der Kniff ist, wie bei jedem Festmahl, dass alles zusammen ankommt. Grillt zuerst den Kabeljau, weil er dicker ist, und zuletzt die Gelbschwänze, weil sie schnell gar sind. Der Raptor ruht, während der Fisch gart, und das ist allen recht. Legt alles auf das größte Brett, das Ihr besitzt, den Raptor in die Mitte wie einen General und die Fische in Reihen um ihn herum. Ein Festmahl ist eine Aufführung. Das Publikum isst sie. Ihr verbeugt Euch danach am Herd und esst, was übrig ist, und das ist meistens der Kabeljau." },
    [1225763] = { "Ein Bankett ist kein Gericht. Es ist ein Feldzug. Zwölf Dunkelklauenhummer, vier Portionen Schildkrötenfleisch, drei Bussardflügel und ein Beutel erlesener Gewürze, die so heißen, weil der Händler, der sie verkauft, ein Wort für den Preis braucht. Die Hummer werden pochiert, die Schildkröte geschmort, der Bussard gebraten, und alles kommt zugleich auf den Tisch, und darin liegt die wahre Schwierigkeit. Jeder Teil muss im selben Augenblick fertig sein, also beginnt mit dem langsamsten, der Schildkröte, und endet mit dem schnellsten, den Hummern, herausgehoben im Moment, in dem sie rot werden. Ich habe ein solches Bankett für den Adel von Sturmwind gekocht, und ich sage Euch, was ich gelernt habe: Die Gäste erinnern sich an den Hummer, und der Koch erinnert sich an das Timing. An den Bussard erinnert sich niemand. Bereitet ihn trotzdem gut zu. Irgendjemand bemerkt immer, was Ihr ausgelassen habt." },
    [1229737] = { "Bevor es ein Gericht gibt, gibt es ein Feuer, und bevor es ein Feuer gibt, gibt es einen Koch, der weiß, wie man eines baut. Einfaches Holz, locker geschichtet, damit die Luft hindurchziehen kann, unten angezündet und dann in Ruhe gelassen. Ein Koch, der kein Feuer machen kann, ist ein Gast. Ein Koch, der ein tosendes macht, ist ein Angeber. Das richtige Feuer zum Kochen ist das, welches aufgehört hat, Euch beeindrucken zu wollen, und sich zu Glut beruhigt hat." },
    [1247741] = { "Ein Fisch, den ich auf dem Markt von Sturmwind noch nicht gesehen habe, obwohl die Fischer von ihm sprechen, wie sie von jedem Fisch sprechen, den sie nicht gefangen haben. Der Heilbutt ist ein breiter, weißer, großzügiger Fisch, und einer mit Stacheln, so sagt man mir, wehrt sich an der Leine und in der Küche. Gart ihn in einem dicken Stück, sanft, bis die Flocken unter einem Finger eben auseinandergehen. Zu lange gegarter Heilbutt ist Kreide. Wenn mir jemand einen bringt, werde ich mehr sagen, und ich werde es als Erster sagen." },
    [1249957] = { "Die Friedensblume ist die blasse Blume, die an jedem Wegrand wächst, und die Trolle der Frostmane in Dun Morogh brauen, wie man mir sagt, diesen Tee daraus, bevor sie unsere Zwerge angreifen. Das finde ich irgendwie beruhigend. Zwei Friedensblumen auf ein Maß Quellwasser, knapp unter den Siedepunkt gebracht und ziehen gelassen, bis das Wasser die Farbe von Stroh annimmt. Lasst es kochen, und es schmeckt nach Heu. Lasst es ziehen, und es schmeckt nach einem stillen Nachmittag. Die Trolle haben offenkundig nie einen erlebt." },
    [1249958] = { "Maguskönigskraut ist ein Kraut mit einer hohen Meinung von sich selbst, und königlicher Tee ist Maguskönigskraut, in eiskalter Milch gezogen, was auch der Milch eine hohe Meinung von sich selbst verleiht. Die Milch wird sanft erwärmt und das Kraut darin gelassen, bis sie einen blassvioletten Schimmer und den Duft eines feinen Gartens annimmt. Lasst sie nicht kochen. Gekochte Milch bildet eine Haut, und eine Haut auf königlichem Tee ist die Krone eines Bauern. Ich serviere ihn Adligen, die die Ironie weniger genießen als ich." },
    [1249959] = { "Lebenswurz, in Melonensaft gezogen, was eine seltsame Art ist, Tee zu machen, und eine gute. Der Melonensaft wird erwärmt, bis er eben dampft, und die Lebenswurz, gewaschen und in Scheiben geschnitten, darin gelassen, bis der Saft dunkel wird und zugleich nach Erde und nach Sommer riecht. Seiht ihn sorgfältig ab. Eine Wurzel, die zu lange darin bleibt, lässt den Tee nach dem Boden schmecken, in dem sie wuchs, und der Boden war nicht eingeladen. Die Murlocs von Hillsbrad tragen dieses Rezept bei sich, was ich als Beweis nehme, dass selbst Murlocs ihre Nachmittage haben." },
    [1249960] = { "Ein Tee für nach dem Kampf, wie ich dem Namen entnehme, aus süßem Nektar und Blassblatt. Blassblatt ist das Kraut, das Schurken kauen, um ungesehen zu bleiben, was mir eine merkwürdige Gabe für die Verwundeten scheint. Erwärmt den Nektar, bis er dampft, lasst das Blassblatt darin ziehen und seiht es ab, bevor es bitter wird. Ich habe dieses Rezept noch nirgends verkauft gesehen. Wenn es so weit ist, werde ich es kaufen, und dem Heiler, der es geschrieben hat, einen ausgeben." },
    [1249961] = { "Sonnengras, in Mondbeerensaft gezogen, was ein Scherz über Sonne und Mond ist, den das Rezept nicht zu erklären geruht. Der Saft wird erwärmt und das Sonnengras darin gelassen, bis das Getränk golden wird und nach Heu am Nachmittag riecht. Seiht ihn ab und serviert ihn warm. Es ist ein fröhliches Getränk, was selten ist, und ich habe nichts Bissiges darüber zu sagen, was noch seltener ist." },
    [1249962] = { "Bergsilberweisling, in Trichterwindentau gezogen, ein Tee also ganz aus Dingen, die schwer zu finden sind. Darum, vermute ich, heißt er der Tee des Weisen. Erwärmt den Tau sanft, lasst den Silberweisling ziehen, bis das Getränk blass ist und nach kalter Luft und Stein riecht, und seiht es dann ab. Es ist ein sehr guter Tee. Es ist auch eine teure Art, sich weise zu fühlen, und das ist die verbreitetste." },
    [1249963] = { "Ein Smoothie mit einem Giftbeutel darin, der laut dem Händler unbedenklich ist, gesagt mit der Zuversicht eines Mannes, der noch keinen getrunken hatte. Quellwasser, milde Gewürze und der kleine Giftbeutel, zerdrückt und durchgeseiht, sodass nur seine Schärfe bleibt und nicht sein Zweck. Schüttelt ihn kräftig und trinkt ihn kalt. Er brennt auf dem Weg nach unten auf der Zunge, und darum geht es wohl. Ich verkaufe nichts dergleichen. Vielleicht später, falls der Händler überlebt." },
    [1249964] = { "Schleimig nennt er sich, und es ist der treffendste Name in diesem Kapitel. Eiskalte Milch, milde Gewürze und Spinnensekret, geschüttelt, bis das Sekret aufhört, am Boden des Glases zu schmollen, und einwilligt, ein Getränk zu sein. Serviert ihn sofort, denn er bleibt nicht lange einsichtig. Ich hätte ihn nicht erfunden. Ich habe allerdings einem Gnom zugesehen, wie er drei davon trank, und das sagt, glaube ich, mehr über Gnome als über den Smoothie." },
    [1249965] = { "Ich werde nicht versuchen, den Namen dieses Getränks auszusprechen. Ich habe einen Murloc es versuchen hören, und es ging für keinen von uns beiden gut aus. Melonensaft, scharfe Gewürze und eine Murlocflosse, zusammen geschüttelt, bis die Flosse ihren Geschmack an den Saft abgibt. Er schmeckt süß, dann scharf, dann nach etwas, das ich nur Küste nennen kann. Die Murlocs, vermute ich, trinken ihn als Beleidigung für uns andere. Es ist, das gebe ich zu, eine gut gemachte Beleidigung." },
    [1249966] = { "Ein Smoothie mit einem Zahn darin. Ich habe das Rezept zweimal gelesen, dann ein drittes Mal mit Brille. Süßer Nektar und scharfe Gewürze, dazu ein großer Fangzahn, zu feinem Pulver gemahlen und eingerührt, was das Getränk kreidig macht und es, so sagt man mir, zum Liebling von Leuten macht, die gegen Bären kämpfen. Seiht ihn gut ab. Ein Getränk mit Grieß darin ist ein Getränk mit einer Beschwerde darin, und Beschwerden nehme ich nicht an." },
    [1249967] = { "Mondbeerensaft, feine Gewürze und ein kleiner Flammenbeutel, angestochen und ins Glas gedrückt. Die feinen Gewürze sind, vermute ich, dabei, um sich für den Flammenbeutel zu entschuldigen. Schüttelt ihn kräftig und trinkt ihn schnell, bevor die Hitze sich entscheidet. Es ist das einzige Getränk, das ich kenne, das die Hände von innen wärmt. Die Feuermagier im Magierviertel bestellen ihn krugweise, und das sagt Euch alles, was Ihr über Feuermagier wissen müsst." },
    [1249968] = { "Trichterwindentau, eine große Menge feiner Gewürze und eine tückische Klaue, fein gemahlen. Tückisch ist das richtige Wort. Die Klaue gibt dem Getränk eine dunkle, bittere Kante, die die Gewürze ihr ganzes Leben lang zu glätten versuchen, und es gelingt ihnen nie ganz. Schüttelt ihn kalt. Ich weiß nicht, wer das zum Vergnügen trinkt. Ich weiß, wer es auf eine Wette hin trinkt, und mehrere von denen habe ich aus meiner Küche geleitet." },
    [1250142] = { "Frikadellen sind klein und zahlreich, und so mögen junge Köche alles. Der Hirsch wird mit scharfen Gewürzen fein gehackt und zu Runden von der Größe einer Handfläche gedrückt. Drückt sie einmal und nie wieder: Eine zweimal gedrückte Frikadelle gibt ihren Saft der Pfanne statt dem Gast. Ich billige kein Essen, das dazu gemacht ist, im Stehen gegessen zu werden. Diese billige ich, im Stehen, und ich bin nicht stolz darauf." },
    [1250143] = { "Ein Rollbraten ist plattiertes Fleisch, gefüllt und gerollt, und der erhabene wird aus Bussard gemacht, und das ist das Einzige an ihm, was erhaben ist. Drei Flügel, entbeint und flach geklopft, um feine Gewürze gerollt und gebunden. Es ist fummelige Arbeit, und an fummeliger Arbeit wird ein Koch geprüft. Rollt ihn fest, röstet ihn sanft und schneidet ihn in Scheiben. Die Scheiben zeigen Eure Messerarbeit. Sorgt dafür, dass sie etwas zeigen, das Ihr unterschreiben würdet." },
    [1250144] = { "Ein Ragout ist ein alter Eintopf vom Bauernhof, langsam gegart aus klein geschnittenem Fleisch, und hier ist das Fleisch Fledermaus. Ich hätte keine Fledermaus gewählt. Die Fledermaus hätte mich nicht gewählt. Drei Flügel, gehackt, mit feinen Gewürzen, und kleine Hitze für den größten Teil eines Abends, bis die Sehnen zu etwas weich werden, das man einem Gast vorsetzen kann. Wer immer es erfunden hat, war arm und klug. Ich achte die Klugen, und ich habe über die Jahre gelernt, den Armen zu verzeihen." },
    [1250145] = { "Schildkröte, geschmort statt passiert, was sie zu einem Bauerngericht macht, und kein schlechteres deswegen. Drei Portionen Schildkrötenfleisch und eine großzügige Handvoll feiner Gewürze, geköchelt, bis das Fleisch zerfällt. Siebt es nicht, ganz gleich, was Euch ein feinerer Koch einreden will. Der Biss ist der Sinn eines Eintopfs, und ein Schildkröteneintopf hat sehr viel Biss, einiges davon beabsichtigt. Serviert ihn dick, in Schüsseln, ohne Entschuldigung dafür, dass er ehrlich ist." },
    [1250146] = { "Pfefferflanke heißt es, und es ist kein Pfeffer darin. Es gibt die Flanke des roten Wolfs und feine Gewürze, und die Gewürze tun die Arbeit des Pfeffers gut genug, dass sich niemand beschwert. Bratet die Flanke scharf an, lasst sie dann ruhen, während die Pfanne abkühlt, und gießt die Säfte wieder darüber. Tranchiert sie niemals auf dem Brett, auf dem sie angebraten wurde. Das Brett erinnert sich an die Hitze, und das Fleisch auch." },
    [1250147] = { "Geschnetzeltes, sagt das Rezept, und beschreibt dann etwas ganz anderes. Das Gericht ist schlicht genug, um sich selbst zu erklären: Großbärenfleisch, dünn geschnitten, mit feinen Gewürzen geschichtet und langsam geröstet, bis die Schichten verschmelzen. Der Kniff ist, es kalt zu schneiden, denn warmes Fleisch reißt unter dem Messer. Wer diesem Gericht seinen Namen gab, hat es wohl nie gekocht. Das Gericht selbst hat nichts zu verbergen, und ich mag es lieber als seinen Namen." },
    [1250148] = { "Ein Hirschsteak, dampfend serviert, also sofort serviert, und so sollte jedes Steak serviert werden, und so wird fast keines serviert. Drei Stücke Hirsch, feine Gewürze tief eingerieben, ein sehr heißes Eisen. Der Dampf ist der Sinn der Sache. Wenn es ohne Dampf auf den Tisch kommt, hat es irgendwo gewartet, wo es nicht hätte warten sollen, und jemand in Eurer Küche schuldet Euch eine Entschuldigung, und sehr wahrscheinlich ein neues Steak." },
    [1250149] = { "Ein Jägername für ein Gericht, als wäre der Tiger von einem Blitz gefangen worden. Der Tiger wurde von einem Jäger und sehr viel Warten gefangen. Das Steak jedoch verdient seinen Namen: drei Stücke Tiger, feine Gewürze und das heißeste Feuer, das Ihr machen könnt, für die kürzeste Zeit, die Ihr ertragt. Schnell zuschlagen, lange ruhen. Bei der zweiten Hälfte verlieren die meisten Köche die Nerven." },
    [1250150] = { "Ein Rezept, das man mir beschrieben hat, das ich aber nie verkauft gesehen habe, und das ist die gefährlichste Sorte. Der Raptor hat längst aufgehört zu toben, wenn er die Pfanne erreicht, also muss der Name die Gewürze meinen, und davon gibt es eine Menge. Gart die Rippchen bei niedriger Hitze, bis sich das Fleisch vom Knochen löst, dann über starker Hitze, damit die Kruste fest wird. Serviert sie nur Leuten, die danach gefragt haben. Das sage ich nicht von jedem Gericht." },
    [1250151] = { "Die Brust ist das Stück eines geduldigen Kochs, und die Bärenbrust ist das Stück eines Heiligen. Sie ist der zäheste Teil des Tieres, nichts als harte Arbeit und alter Muskel. Reibt sie mit scharfen Gewürzen ein und gebt ihr das kleinste Feuer, das Ihr am Brennen halten könnt, und einen ganzen Tag. Irgendwann am Abend gibt sie auf und zerfällt unter einer Gabel. Die Stunde kann ich Euch nicht sagen. Ich kann Euch sagen, dass der Koch, der zu oft nachsieht, sie nie erreicht." },
    [1250152] = { "Prähistorisch, als hätte der Raptor seit Anbeginn der Welt darauf gewartet, mit zwei Gabeln zerpflückt zu werden. Vielleicht hat er das. Drei Portionen Raptor und eine Menge feiner Gewürze, dann das kleinste Feuer, das Ihr den größten Teil eines Tages hüten könnt. Das Fleisch ist fertig, wenn es bei einer Berührung zerfällt. Zerpflückt es mit Gabeln, niemals mit einem Messer. Ein Messer macht geschnittenen Raptor daraus, und geschnittener Raptor ist ein anderes und geringeres Buch." },
    [1250153] = { "Die Zwerge behaupten, die Roulade erfunden zu haben, wie sie fast alles erfunden haben wollen, und das Gericht ist gerolltes Fleisch: dünne Scheiben Raptor, um scharfe Gewürze gerollt und gebunden. Gerolltes Fleisch gart von außen nach innen, also muss die äußere Lage dünn sein, sonst bleibt die Mitte roh. Bräunt die Rollen auf jeder Seite, senkt dann die Hitze und lasst sie in Ruhe. Wenn die Schnur verkohlt, schneidet sie ab. Wenn Ihr einem Gast die Schnur serviert, verdient Ihr den Blick, den Ihr bekommt." },
    [1250154] = { "Zweifach gewürzt, und ausnahmsweise sagt ein Gericht die Wahrheit über sich selbst. Der Raptor wird einmal eingerieben, bevor er geschnitten wird, und einmal, nachdem er gegart ist, und das zweite Mal nicht für den Geschmack, sondern für die Kruste. Raptorfleisch ist mager und trocknet schnell aus. Schneidet es quer zur Faser, so dünn, dass man eine Kerze hindurchscheinen sieht, und gebt es dem Feuer für einen Atemzug, nicht länger. Ein Rezept, das ich nicht erfunden habe und das ich erfunden hätte, mit etwas Zeit." },
    [1250155] = { "Rührei ist die erste Prüfung für die Geduld eines Kochs, und riesiges Rührei ist dieselbe Prüfung in einer größeren Pfanne. Zwei Rieseneier und scharfe Gewürze, miteinander verquirlt und bei kleiner Hitze gerührt, langsam, unablässig, bis sie zu weichen Flocken stocken. Eine heiße Pfanne macht Gummi daraus. Eine sanfte Pfanne macht Seide daraus. Die meisten Köche ertragen es nicht, so lange zu rühren. Die meisten Köche sollte man nicht in die Nähe eines Rieseneis lassen." },
    [1250156] = { "Ein Rezept, das in den Nestern von Raptoren auftaucht, was entweder ein Scherz oder eine Warnung ist. Die Happen werden aus dem Ei gemacht, nicht aus dem Tier, und ein Raptorei ist schwerer und gehaltvoller als alles, was je eine Henne gelegt hat. Würzt es großzügiger, als Ihr es für schicklich haltet, denn der Dotter trinkt jedes Körnchen. Gart die Happen klein und schnell. Ein langsam gegartes Raptorei wird aus Trotz zu Gummi. Ich vermute, die Mutter hat es ihm beigebracht." },
    [1250157] = { "Ein Frühstücksomelett, mit einem Ei und einer offen gesagt beunruhigenden Menge milder Gewürze. Wer immer dieses Rezept geschrieben hat, ist hungrig und wütend aufgewacht. Das Geheimnis jedes Omeletts sind Hitze und Tempo: eine heiße Pfanne, das Ei geschlagen, bis es nur noch eine Farbe hat, und eine Gabel, die die Ränder einzieht, sobald sie stocken. Klappt es zusammen, solange die Mitte noch weich ist. Das Rezept wurde im Rotkammgebirge gefunden, im Nest eines Kondors, was die Wut erklärt, wenn auch nicht die Gewürze." },
    [1250158] = { "Linguine, sagt man mir, sind lange, flache Nudeln aus irgendeiner fernen Küche. Im Rezept ist keine Nudel. Es gibt scharfes Muschelfleisch, eine Menge davon, in lange Bänder geschnitten und in feinen Gewürzen geschwenkt, und daher kommt wohl der Name. Gart die Bänder einen Augenblick in einer heißen Pfanne und serviert sie sofort. Sie verheddern sich wie Nudeln und essen sich wie Muscheln. Ich billige die Täuschung." },
    [1252566] = { "Schalkflosse. Jemand hat einen Fisch so genannt, und jemand anders war einverstanden. Das Rezept taucht im Rotkammgebirge in den Bündeln von Gnollen und Murlocs auf, die nicht für ihre Küchen bekannt sind, also nehme ich an, sie haben es jemandem gestohlen, der etwas vom Kochen verstand. Der Fisch ist klein, leuchtend und zart. Eine Prise milder Gewürze, eine heiße Pfanne, sehr wenig Zeit. Der Name verspricht Schalk. Das Gericht liefert ein Abendessen, und das ist besser." },
    [1255241] = { "Ein Eintopf mit einer verderbten Blume, die jemand gereinigt hat, was sie, wie man mir versichert, wieder zu einem Kraut macht und nicht länger zu einer Gefahr. In solchen Dingen verlasse ich mich auf das Wort der Druiden, und in sehr wenigen anderen. Hirschfleisch und ein Riesenei geben ihm Kraft, das Ei am Ende hineingeschlagen, damit die Brühe seidig wird. Man kocht ihn, so sagt man mir, für jene, die aus dem Teufelswald zurückkehren, und sie verdienen eine freundlichere Küche als den Wald, den sie verlassen haben." },
    [1262978] = { "Cookie ist der Murloc, der tief in den Todesminen die Küche der Bruderschaft der Defias führt, und man sagt mir, er kocht mit einer Kelle in der einen Hand und einem Hackbeil in der anderen und kümmert sich wenig darum, welches von beiden er an Besuchern anwendet. Sein Rezept wurde von Abenteurern aus der Mine getragen, die es ihm abgenommen hatten, und ich habe es mit einem beruflichen Interesse studiert, auf das ich nicht stolz bin. Zwei Portionen eigenartiges Fleisch und eine Portion schweres Kodofleisch, langsam mit feinen Gewürzen geschmort, bis der Kodo weich geworden und das Eigenartige noch eigenartiger geworden ist. Es ist ein Festmahl, also dazu gemacht, von einer gemeinsamen Platte geteilt zu werden, was ich unhygienisch finde und die Defias vermutlich notwendig. Das Gericht ist hervorragend. Der Koch ist ein Murloc und ein Verbrecher. Ich würde ihn morgen einstellen, wenn er das Hackbeil an der Tür ließe." },
    [1263067] = { "Ein Eisenofen, sagt das Rezept, und verlangt dann Mehl, Quellwasser und feine Gewürze, und überhaupt kein Eisen. Ich habe es mehrmals gelesen. Ich glaube, der Ofen ist das Gefäß, und das Rezept ist das, was als Erstes hineinkommt, eine große Menge Teig, mit Gewürzen geknetet und gebacken, um das Eisen einzubrennen, so wie man eine neue Pfanne einbrennt. Was immer sein Geheimnis ist, es ist das Rezept eines Meisters, und ich besitze es noch nicht, was mich mehr ärgert, als ich höflich sagen kann." },
    [1270632] = { "Ein Keks für die kleinen Tiere, die Abenteurern überallhin folgen, und gemacht, wie ich anmerke, aus nichts als Mehl, was Euch verrät, wie oft man die kleinen Tiere um Rat fragt. Fünf Maß Mehl, mit leichter Hand geknetet und gebacken, bis sie blassgolden sind. Man sagt mir, die Tierchen lieben sie. Ich habe eine Katze einen fressen sehen. Die Katze sah mich danach an, als erwarte sie mehr, und das ist die einzige Kritik, die ein Haustier je abgegeben hat." },
    [1270633] = { "Ein Soufflé ist ein Ei, das man überredet hat, aufzustehen, und das Soufflé vom Himmelswall, benannt nach irgendeiner Höhe, die ich nie besucht habe, steht höher als die meisten. Zwei Eier und ein wenig Mehl, das Eiweiß geschlagen, bis es Spitzen hält, sanft untergehoben und gebacken, ohne ein einziges Mal die Ofentür zu öffnen. Das ist die Regel. Öffnet die Tür, und es fällt zusammen, und es wird sich nie wieder erheben, weder für Euch noch für sonst jemanden. Das Soufflé ist das einzige Gericht, das für immer schmollt." },
    [1270635] = { "Krebssaison nennen sie den Auftrag, die dieses Rezept lehrt, als hätten Krebse eine Saison und wären nicht einfach immer da, am Rand jedes Strandes herumkrabbelnd. Die Scheren werden geknackt, das Fleisch herausgepult und mit ein wenig Mehl gebunden, dann in kleinen Happen ausgebacken. Nehmt so wenig Mehl, wie Ihr nur könnt. Es hält den Krebs zusammen. Es darf nicht zum Gericht werden. Ein Happen, der nach Brot schmeckt, ist ein Happen, der Euch über den Strand belogen hat." },
    [1283400] = { "Sternenholz brennt heißer und sauberer als das gewöhnliche, und ein Geselle der Kochkunst sollte den Unterschied kennen, bevor man ihn an ein besseres Feuer lässt. Das Rezept wurde in den Höhlen des Wehklagens gefunden, bei den Druiden, die dort vom Weg abgekommen sind, und das ist ein weiter Weg für ein besseres Lagerfeuer. Schichtet es auf dieselbe Weise, locker, und lasst es weiter herunterbrennen, bevor Ihr kocht. Ein heißeres Feuer verzeiht weniger. Genau das bedeutet es, Geselle zu sein." },
    [1291341] = { "Dicke Holzscheite, die eine Ewigkeit brauchen, bis sie Feuer fangen, und dann einen ganzen Abend brennen, beständig wie ein Herd. Dies ist das Feuer eines Experten, und es lehrt die Lektion eines Experten: Die lange, gleichmäßige Hitze ist das Warten wert. Legt die Scheite im Viereck, lasst eine Lücke für die Luft, entzündet das Anmachholz darunter und habt Geduld. Ich habe dieses Rezept noch nirgends verkauft gesehen. Ich habe Köche gesehen, die glaubten, es nicht zu brauchen, und sie wurden nie ganz zu Experten." },
    [1294014] = { "Marmelade aus den Beeren des Hyjal, die an den Hängen eines Berges wachsen, der, wie man mir sagt, heilig ist, und der, dessen bin ich mir ziemlich sicher, sehr kalt ist. Drei Maß Beeren und feine Gewürze, langsam eingekocht, bis ein Tropfen auf einem kalten Teller Falten wirft, wenn man ihn anstößt. Das ist Eure Probe. Zu flüssig, und Ihr habt eine Soße gemacht. Zu fest, und Ihr habt einen Ziegelstein gemacht. Süßtatze nennt man sie, nach den Bären, die die Sträucher plündern. Die Bären haben recht, was die Beeren angeht." },
    [1295805] = { "Ein Eintopf der Küste, gemacht aus dem, was die Küste bietet, und das sind Krebse und, zu meinem bleibenden Bedauern, Murlocaugen. Die Augen geben der Brühe Kraft, wie im Eintopf von Westfall, und ich habe gelernt, nicht mehr mit ihnen zu streiten. Das zarte Krebsfleisch kommt am Ende hinein, damit es süß bleibt. Scharfe Gewürze von Anfang bis Ende. Das Ergebnis ist salzig und reichhaltig und riecht nach dem Meer, bevor irgendjemand es aufgeräumt hat." },
    [1295834] = { "Ein Rezept aus den Flusslanden, verkauft von einer Frau, die keinen Grund sah, ihm einen großartigeren Namen zu geben, und sie hatte recht. Eberfleisch, eine ordentliche Menge, mit einer Prise milder Gewürze, am Knochen geröstet, bis das Fett knistert. Das ist alles. Ich habe mein Leben damit verbracht, Köchen beizubringen, der Versuchung zu widerstehen, mehr zu tun, und hier ist eine Bäuerin, die es nie lernen musste. Lasst es ruhen, bevor Ihr es tranchiert. Schlichtes Essen verzeiht nichts, und darum gelingt es so selten." },
    [1319313] = { "Ein Fisch, der eine Rüstung trägt, was nur gerecht scheint, wenn man bedenkt, was mit denen geschieht, die keine tragen. Die Platten lösen sich mit einem schweren Messer und etwas Geduld, und das Fleisch darunter ist fest und blass wie ein Hummerschwanz. Feine Gewürze, mäßige Hitze, und überstürzt es nicht. Gepanzerte Fische lassen sich Zeit beim Garen und Zeit beim Verlassen ihrer Schale. Das solltet Ihr auch." },
  },
  eunice = {
    [2538] = { "Das erste Gericht jedes Kochs, ob lebendig oder nicht. Man lernt es unterwegs, mit einem Messer und einem Feuer, denn es gibt immer einen Wolf, und es gibt immer jemanden, der Hunger hat. Hört ihm zu. Wolfsfleisch zischt, wenn es zum ersten Mal die Hitze trifft, und wird still, wenn sich die Außenseite geschlossen hat. Wendet es einmal, bei der Stille. Meine Schüler wollen darin herumstochern. Ich lasse sie, einmal, und dann lasse ich sie essen, worin sie herumgestochert haben." },
    [2539] = { "Das lehre ich am zweiten Tag, nach dem verkohlten Wolf, damit meine Schüler lernen, dass Gewürz keine Korrektur ist. Reibt es vor dem Feuer ins Fleisch. Kommt es erst am Ende dazu, riecht es nach Gewürz und nach Wolf, zwei Fremde am selben Tisch, die nicht miteinander reden. Kommt es am Anfang dazu, riecht es nach Abendessen. Die Lebenden sagen mir, der Unterschied sei auf der Zunge genauso deutlich." },
    [2540] = { "In Lordaeron rösteten wir zur Ernte Eber, in einer Grube hinter der Scheune, oder hinter dem Gasthaus, oder hinter irgendjemandes Scheune. An die Grube erinnere ich mich deutlich und an die Scheune überhaupt nicht. Hier unten ist es ein schlichtes Gericht für schlichte Tage. Röstet das Fleisch in Stücken, niemals im Ganzen: Ein ganzer Eber braucht den ganzen Tag, und die Leute, die darauf warten, haben ihn nicht. Wenn das Fett anfängt, süß statt scharf zu riechen, ist es fertig." },
    [2541] = { "Kojoten fressen, was immer die Welt fallen lässt, und ihr Fleisch erinnert sich an jede Mahlzeit. Es verlangt kein Gewürz, nur eine heiße Pfanne und einen Koch, der sich nicht dafür entschuldigt. Bratet es an, bis sich die Ränder wellen und der Geruch von Blut zu gerösteten Nüssen wechselt, nehmt es dann von der Hitze und lasst es in Ruhe. Ein Kojotensteak ist nie zart, sagen mir die Lebenden, kauend. Es ist ehrlich, und ehrliches Essen hält einen Reisenden auf einem langen Weg auf den Beinen." },
    [2542] = { "Eine Bauernpastete aus dem Süden, und in Lordaeron machten wir eine sehr ähnliche, mit Schweineleber oder Kalbsleber, an den Tagen, an denen der Metzger da gewesen war. Ich sehe die Pastetenform vor mir. Sie war blau, mit einer abgeschlagenen Stelle am Rand, und sie stand zum Abkühlen auf dem Fensterbrett, und ich weiß nicht, wessen Fenster es war. Die Leber des Geiferzahns ist kräftig und dunkel. Legt sie vor dem Kochen in kaltes Wasser, um die Bitterkeit herauszuziehen, würzt sie dann mit milden Gewürzen und gebt ihr einen langsamen Ofen. Schnell gegarte Leber riecht nach Eisen und wird grau. Langsam gegarte Leber riecht nach etwas Vollem und Sanftem, wie warme Erde nach dem Regen, und dann ist sie fertig. Meine Schüler machen sie für die Lebenden, die hier durchkommen, und die Lebenden essen sie, als wäre sie ihnen vertraut. Vielleicht ist sie das, für sie." },
    [2543] = { "Ein Bauerneintopf aus dem Süden, gemacht aus dem, was das Land gibt, wenn es sehr wenig gibt: Geier, die Schnauze eines Geiferzahns und das Auge eines Murlocs, für das ich mich nicht entschuldigen werde. In Lordaeron hatten wir einen ähnlichen Eintopf, gemacht aus dem, was die Felder und der Fluss übrig ließen. Ich erinnere mich an den Topf. Ich erinnere mich, dass er schwarz und schwer war und dass sich immer jemand die Hand daran verbrannte. Wessen Hand, kann ich Euch nicht mehr sagen. Das Auge gibt der Brühe ihre Kraft, also lasst es nicht weg, um einen zimperlichen Gast zu schonen. Zimperliche Gäste dürfen hungrig bleiben. Lasst ihn köcheln, bis der Geier aufgibt, und das dauert länger, als Ihr denkt. Reisende aus dem Süden erzählen mir, dass die Höfe dort jetzt leer stehen. Der Eintopf hat die Höfe überlebt, wie Eintöpfe es meistens tun." },
    [2544] = { "In Southshore machte man an jedem Feiertag Krebsküchlein, oder an jedem zweiten, und die Frauen stritten durch das Fenster des Gasthauses über die Gewürze, oder durch das der Bäckerei. An das Streiten erinnere ich mich besser als an die Küchlein. Löst das Kriecherfleisch sauber aus, gebt eine Prise milder Gewürze dazu und drückt es mit den Händen zusammen. Bratet es, bis die Außenseite fest wird. Fällt es auseinander, drückt das nächste Mal fester. Springt es zurück, drückt weniger. Das Streiten ist freiwillig." },
    [2545] = { "Knackt die Schere, bevor sie das Feuer trifft, damit die Hitze das Fleisch im Inneren erreicht, statt es in seiner eigenen Schale zu dämpfen. Eine Prise milder Gewürze in den Riss. Ein kurzes, heißes Feuer. Ihr werdet hören, wie das Fleisch in der Schale zu brutzeln beginnt, ein kleines, geschäftiges Geräusch, und wenn es aufhört, ist die Schere fertig. Pult sie mit einer Gabel aus. Die Schale geht an die Apotheker, die alles haben wollen." },
    [2546] = { "Keine Soße, nur Gewürz und ein kleines Feuer und ein ganzer Nachmittag, so wie die Höfe sie am Ende der Ernte gegart haben, oder an ihrem Anfang, ich habe vergessen, welches. Die Rippchen sind fertig, wenn die Knochen an den Enden einen Finger breit hervorschauen und der Geruch von Fleisch zu etwas gewechselt ist, das näher an geröstetem Brot liegt. Ich serviere sie auf Papier, Leuten, die mit den Händen essen und denen es gleich ist, wer zusieht. In Undercity sind das die meisten." },
    [2547] = { "Spinne und Kondor, zusammen geschmort. Der Kondor ist zäh und die Spinne nicht, also kommt der Kondor zuerst hinein und die Spinne viel später. Gebt sie zusammen hinein, und Ihr werdet die Spinne zerkochen riechen, eine scharfe, saure Note, lange bevor der Kondor auch nur annähernd fertig ist. Es ist ein Gericht des Südens, von Leuten, die mehr Spinnen hatten, als ihnen lieb war. Diese Leute verstehe ich sehr gut." },
    [2548] = { "Zwei Reihen Rippchen und scharfe Gewürze, alle paar Minuten gewendet, damit das Fett das Fleisch begießt, während es schmilzt. Das Wenden ist das Rezept. Eine sich selbst überlassene Rippe verbrennt unten und schmollt oben. Eine oft gewendete Rippe kommt glänzend und großzügig heraus. Das hat mir ein Bauer beigebracht, ein Nachbar, glaube ich, mit einem roten Bart, oder einer roten Scheune. Ich gebe es den Schülern, die glauben, Kochen sei Warten. Das ist es nicht. Es ist Aufmerksamkeit, während man wartet." },
    [2549] = { "Würzkräuter aus Stormwind, steht auf dem Päckchen, und sie riechen genau so, wie ich den Markt der alten Hauptstadt in Erinnerung habe, das heißt, ich kann Euch nicht sagen, ob die Erinnerung Sturmwind gilt oder Lordaeron oder einem Traum. Dem Wolf ist das gleich. Steckt das Fleisch mit Lücken zwischen den Stücken auf, damit die Hitze jede Seite erreicht, und horcht, wann das Fett spritzt. Wenn es aufhört zu spritzen und anfängt zu singen, wendet die Spieße." },
    [2795] = { "Ein Gericht der Zwerge, was heißt, dass es mit einer Geschichte darüber kommt, wessen Großvater es erfunden hat, und die Geschichte ändert sich mit dem, der sie erzählt. Ich ergreife keine Partei. Die Rippchen und das Malzbier sind ehrlich, wer immer sie zuerst gekocht hat. Jeder Zwerg, von dem ich gehört habe, begießt von der ersten Minute an und gibt dann dem Feuer die Schuld an dem, was folgt. Röstet die Rippchen blank, bis das Fett klar läuft, und beginnt erst dann mit dem Malzbier, immer ein wenig, damit es zu einer Glasur wird. Wenn es nach verbranntem Zucker riecht, habt Ihr es übertrieben. Wenn es nach Brot und Rauch riecht, liegt Ihr genau richtig. Die Todeswachen verlangen dieses Gericht beim Namen, und das ist mehr, als sie für ihre Feldwebel tun. Ich mache es an Festtagen, und an den Tagen, die einen brauchen." },
    [3370] = { "Krokilisk erreicht Undercity aus dem Sumpfland über Leute, die lieber nicht sagen, wie. Ich frage nicht, und sie sind dankbar dafür. Das Fleisch ist blass und fest, mehr Fisch als Tier, und es will eine Prise Gewürz und sehr wenig Zeit. Gart es einmal. Ein zweites Mal erhitzter Krokilisk riecht nach dem Sumpf, und den Sumpf hat niemand bestellt. Serviert es sofort, dem, der am nächsten steht." },
    [3371] = { "Jeden Herbst machten die Bauernhäuser von Lordaeron Blutwurst, und jeden Herbst kannte irgendjemandes Großmutter die einzig richtige Art. Meine schwor auf Thymian. Oder auf Salbei. Ich war mir jahrelang sicher. Hier unten bindet das Spinnensekret sie, wo es einst das Blut tat, und die Königliche Apothekervereinigung versichert mir, es sei unbedenklich für die Lebenden, und das ist mehr, als sie über die meisten Dinge sagt. Die Lebenden kommen für einen Nachschlag wieder, die einzige Kritik, der ich traue. Brüht die Würste, bevor sie die Pfanne sehen. Eine Wurst, die platzt, wurde von jemandem in Eile gestopft." },
    [3372] = { "Zwei Murlocflossen und scharfe Gewürze, geköchelt, bis die Flossen in der Brühe schmelzen und sie dick und reichhaltig hinterlassen, wie Knochenfond. Der Geruch ist das Meer bei Ebbe, was unangenehm klingt und es nicht ist, sobald die Gewürze sich darum kümmern. Die Murlocs an der Küste des Silberwalds hätten Einwände, wenn sie es wüssten. Sie haben gegen das meiste Einwände, laut, und ich habe schon lange aufgehört zuzuhören." },
    [3373] = { "Zartes Krokiliskenfleisch und scharfe Gewürze, eingekocht, bis die Brühe dick und dunkel genug ist, um einen Löffel zu überziehen. Die Farbe sagt es Euch, und der Geruch auch: Wenn er von Sumpf zu gerösteter Nuss wechselt, seid Ihr da. Rührt immer vom Boden her. Einen Gumbo kann ich nicht schmecken, aber einen verbrannten kann ich vom anderen Ende von Undercity aus riechen, und alle anderen, so sagt man mir, auch." },
    [3376] = { "Ein Raptorei und scharfe Gewürze. Das Ei ist gehaltvoller als ein Hühnerei und stockt langsamer, also habt Geduld mit der Mitte. Schlagt es kräftig, gart es schnell, klappt es weich zusammen. Das Seltsame daran, sagt man mir, ist, wie gut es ist. Das kann ich Euch selbst nicht sagen. Ich kann Euch sagen, dass die Leute, die es essen, still werden und dann den Teller ansehen, als schulde er ihnen eine Erklärung." },
    [3377] = { "Spinnenbeine, das Fleisch herausgelöst und mit scharfen Gewürzen zu Küchlein gedrückt, gebraten, bis die Außenseite knusprig wird und die Mitte weich bleibt. Das Klebrige soll in der Mitte bleiben. Wenn es in die Pfanne läuft, hört Ihr es zischen und riecht es anbrennen, und der Kuchen ist verloren. Bratet sie bei gleichmäßiger Hitze, nicht bei heftiger. Ich mache sie blechweise. Spinnen kann Undercity einem Gast immer anbieten." },
    [3397] = { "Die Bären des Südens sind größer als unsere, und ihr Fleisch ist dunkler, mit einem Geruch nach Kiefern und nasser Erde, den die scharfen Gewürze durchschneiden. Bratet das Steak an, bis es nach Rauch und Eisen riecht, und lasst es dann lange ruhen. Ein großes Steak gart nach dem Feuer weiter, und schon mancher Koch hat eines verdorben, indem er es angestarrt hat. Ich sage meinen Schülern, sie sollen weggehen und bis hundert zählen und mir danach sagen, wie es schmeckt. Die meisten kommen bis vierzig." },
    [3398] = { "Die Löwen des Brachlands sind mager und süß nah am Knochen, also bleiben die Koteletts am Knochen. Scharfe Gewürze, ein mäßiges Feuer und häufiges Wenden. Wie scharf sie herauskommen, kann ich Euch nicht sagen. Ich kann Euch sagen, dass die Orcs aus Crossroads jedes Mal mehr Gewürz verlangen und die Trolle weniger, und ich mache zwei Pfannen und lasse sie darüber streiten, wer die richtige hat." },
    [3399] = { "Löwe, als Steak gegart statt gehackt, mit feinen Gewürzen, um die Süße des Fleisches abzurunden. Die feinen Gewürze riechen nach Nelken und warmem Stein. Reibt sie ein, bratet das Steak scharf an und lasst es so lange ruhen, wie Ihr es angebraten habt. Schneidet es quer zur Faser, sonst wehrt es sich im Mund. Den Namen hat jemand geschrieben, der es gegessen hatte und zu beschäftigt war, um ein besseres Wort zu finden." },
    [3400] = { "Schildkröte und feine Gewürze, stundenlang geköchelt und dann durch ein Sieb gestrichen, bis sie glatt ist wie Sahne. Das Sieb ist das Rezept. Der Geruch, während sie köchelt, ist warm und rund, wie Nelken in einem geschlossenen Raum, und er bremst die Leute, die an meiner Küche vorbeigehen. Ich mag ein Gericht, das Leute bremst. Hier unten haben es alle so eilig, irgendwohin zu kommen, wo sie schon gewesen sind." },
    [4094] = { "Im Brachland gibt es mehr Bussarde als Köche, und die Köche haben eine Verwendung für sie gefunden. Der Flügel will scharfe Gewürze, eine lange, niedrige Hitze, um die Sehnen weich zu machen, und dann eine kurze, heftige Flamme, damit die Haut Blasen wirft. Ihr könnt den Wechsel hören. Das Fett hört auf zu flüstern und beginnt zu knistern. Serviert sie heiß und in Mengen. Noch nie hat jemand nur einen einzigen Bussardflügel gegessen." },
    [6412] = { "Ein elfisches Rezept, von einem Baum, so hoch, dass die Nachtelfen angeblich in seinen Ästen kochen. Ich war nie dort, und man erwartet mich auch nicht. Das Rezept kam über drei Händler zu mir, zwei davon ehrlich. Steckt die Spinnenbeine auf einen Spieß und gebt ihnen eine schnelle, heftige Hitze, bis die Schalen knacken wie Zweige im Feuer. Dieses Geräusch ist das Zeichen. Danach kostet Euch jeder Augenblick etwas." },
    [6413] = { "Die Köche von Orgrimmar haben dies mit den ersten Zeppelinen nach Norden geschickt, und Undercity hat Gefallen daran gefunden. Die Überraschung steckt im Stachel. Gegart, bis er von Glas zu Kreide wird, verliert er sein Gift und behält ein angenehmes Knacken. Zu kurz gegart, behält er das Gift, und die Überraschung ist eine andere. Ihr könnt den Wechsel hören. Ein roher Stachel klappert in der Pfanne. Ein garer liegt still." },
    [6414] = { "Die Tauren von Mulgore rösten Kodo so, wie sie die meisten Dinge tun, langsam und ohne Aufhebens. Ich gare es auf dieselbe Weise. Ein Kodo ist ein großes, langsames Tier, und sein Fleisch ist zäh, bis es sich anders entscheidet. Eine Prise Gewürz, ein kleines Feuer und ein Nachmittag. Es ist fertig, wenn es nach warmem Gras und Rauch riecht. Ich kann es nicht schmecken, also habe ich einen taurischen Händler gefragt, der mir sagte, meines sei fast so gut wie das seiner Mutter. Ich habe beschlossen, das Fast für Höflichkeit zu halten." },
    [6415] = { "Frenzys sind nichts als Zähne und Temperament, und ihr Fleisch ist das Weichste an ihnen. Ein Filet zerfällt, wenn Ihr es zu lange anseht. Würzt es leicht, legt es mit der Haut nach unten in eine heiße Pfanne, wendet es einmal. Der Geruch ist süß und kurzlebig, in einem Atemzug verflogen. Wenn er vergeht, ist der Fisch fertig. Das Rezept kommt von der Dunkelküste, über einen Elfen, der nichts von mir wollte als einen fairen Preis, und das ist seltener, als es sein sollte." },
    [6416] = { "Schreiter und Apfel, der erste Eintopf des Brachlands. Der Apfel kommt mit dem Fleisch hinein und kocht sich zu nichts, und wenn Ihr ihn im Topf nicht mehr finden könnt, ist der Eintopf fertig. Der Schreiter ist ein sturer Vogel. Der Apfel redet ihm gut zu. Ich mache ihn für Orcs, die ihre Heimat vermissen, und für Trolle, die nie eine Heimat hatten, die sie vermissen könnten, und sie essen ihn alle auf dieselbe Weise, sehr schnell." },
    [6417] = { "Das Brachland hat mir dies beigebracht, und Undercity hat Gefallen daran gefunden, denn auch uns mangelt es nicht an Ratten, obwohl unsere nicht zum Essen taugen und die Grubenratten des Brachlands schon. Schmort sie lange, bis das Fleisch von den kleinen Knochen fällt, und hebt die Knochen mit Geduld und einem Löffel heraus. Meine Schüler schneiden Grimassen. Ich lasse sie es essen. Dann machen sie es selbst, für die nächsten Schüler, und die Grimassen gehen weiter." },
    [6418] = { "Das Brachland hat mir dies beigebracht, zusammen mit Geduld und Achtung vor allem, was dort überlebt. Der Schwanz einer Donnerechse ist fester Muskel, eingewickelt in eine Haut wie altes Leder. Gart ihn in seinem eigenen Fett mit scharfen Gewürzen, bis die Haut unter einem Löffel knistert. Biegt er sich, ist er nicht fertig. Zersplittert er, ist er vollkommen. Die Orcs essen ihn im Ganzen. Ich schneide ihn in Scheiben, den Möbeln zuliebe." },
    [6419] = { "In den Wäldern über dem Hof gab es Hirsche, und mein Vater, oder mein Onkel, oder ein Nachbar mit einem Bogen, erlegte jeden Herbst einen. Das Gesicht ist fort. Der Geruch des Fleisches in der Pfanne nicht. Wildbret ist mager und stolz und will eine Menge Gewürz und sehr wenig Feuer. Nehmt es heraus, solange die Mitte noch dunkel ist. Mageres Fleisch, durchgegart, schmeckt nach nichts als Reue." },
    [6499] = { "Muscheln sind ehrlich. Sie sagen Euch, wann sie fertig sind, wenn Ihr die Nase über dem Topf behaltet. Der Dampf riecht zuerst süß, dann nach Meer, und das ist der Moment, sie herauszuheben. Muscheln verzeihen nichts, und das achte ich an einem Essen. Ein Reisender aus dem Zeppelin aß einmal zwei Schüsseln im Stehen an meiner Theke und fragte, ob es eine dritte gebe. Es gab keine. Heute mache ich mehr." },
    [6500] = { "Goblins tun zu viel Hitze in alles, auch in ihre Muscheln. Ich lehre es mit berichtigter Hitze. Würziges Muschelfleisch, scharfe Gewürze, ein Feuer, das heiß ist, aber nicht wütend. Der Geruch sagt Euch, wann Ihr aufhören müsst: Wenn die Gewürze nicht mehr roh riechen, sondern geröstet, nehmt die Pfanne weg. Eine wütend gekochte Muschel wird zu Leder. Die Goblins würden Euch das Leder verkaufen und es bissfest nennen." },
    [6501] = { "In Southshore gab es ein Haus, in dem man Muschelsuppe bekam, oder eine Frau, die sie an ihrer Tür verkaufte, und der Geruch zog bis zum Hafen. An den Geruch erinnere ich mich genau und an die Tür überhaupt nicht. Erwärmt die Milch sanft, gebt das Muschelfleisch und eine Prise milder Gewürze hinzu und haltet sie unter dem Köcheln. Milch, die kocht, gerinnt, und Ihr könnt es geschehen riechen, eine saure Kante im Dampf. Wenn Ihr das riecht, fangt neu an." },
    [7213] = { "Eine Riesenmuschel ist dicht und süß, und in Booty Bay röstet man sie für Piraten in scharfen Gewürzen. Schneidet sie in dünne Scheiben, bevor die Hitze sie berührt, damit die Gewürze hindurchdringen, und gebt ihr dann heftig und schnell Feuer. Der Rauch wird Euch die Augen tränen lassen. Daran erkennt Ihr, dass Ihr genug Gewürz genommen habt. Wenn sich der Rauch verzieht, ist auch das Gericht fertig. Serviert es jemandem mit einem starken Magen und einem kurzen Gedächtnis." },
    [7751] = { "Kinder fangen diese an jedem Steg in Tirisfal, und ich kaufe ihnen ihre Eimer ab, denn ein Kind mit einem Fisch verdient eine Münze. Bratet sie im Ganzen in einer heißen Pfanne, eine Handvoll auf einmal. Ihre Augen trüben sich, wenn sie fertig sind, und das ist die freundlichste Art von Zeichen: Der Fisch sagt es Euch selbst. Meine Schüler, die sonst nichts können, können das, und ich lasse sie hier anfangen, damit sie etwas haben, worauf sie stolz sein können." },
    [7752] = { "Die Makrele ist ölig, und das Öl ist der Sinn der Sache. Legt sie mit der Haut nach unten in eine heiße, trockene Pfanne und lasst ihr eigenes Fett sie garen. Der Geruch füllt die Küche, steigt die Treppen hinauf und erreicht die Straße, und immer kommt jemand herunter und fragt, was das ist. So finde ich die meisten meiner Kunden. Der Fisch wirbt besser für sich, als ich es könnte, und er verlangt keinen Lohn." },
    [7753] = { "Der Schlamm steckt in der Haut, nicht im Fleisch, und Ihr könnt ihn riechen, sobald der Fisch die Hitze trifft. Gart ihn im Ganzen über mäßigem Feuer und zieht die Haut ab, bevor Ihr ihn serviert. Das Fleisch darunter riecht nach nichts als Fisch, und genau das will man von einem Fisch. Die Fischer von Tirisfal essen die Haut mit. Sie sagen, sie erinnere sie an den Fluss. Das hätten sie nicht sagen müssen." },
    [7754] = { "Das kalte Wasser von Loch Modan macht einen festeren Fisch als die Frenzys des Südens, und die Zwerge haben ihn ein Supreme genannt, was für sie, wie man mir sagt, ungewöhnlich ist. Eine Prise milder Gewürze, ein schnelles Feuer, und serviert ihn heiß. Der Geruch ist sauber und kalt, wie ein Morgen an einem See. Ich war nie in Loch Modan. Ich war an Seen. Ich stelle mir vor, es ist ähnlich, mit mehr Geschrei." },
    [7755] = { "Welse waren das, was uns der Fluss gab, wenn er uns überhaupt etwas gab, und meine Mutter zog ihnen auf der hinteren Treppe die Haut ab, oder meine Großmutter tat es. Zieht ihm immer die Haut ab. Die Haut riecht nach Flussbett, und Flussbett ist kein Abendessen. Das Fleisch darunter ist weiß und süß und will eine heiße Pfanne und ein einziges Wenden. Ich höre das Messer auf der Treppe noch immer. Die Hand, die es hielt, sehe ich nicht." },
    [7827] = { "Fest und dunkel und reichhaltig, eher wie Fleisch als wie Fisch, und er sollte wie Fleisch gegart werden: außen scharf angebraten und in der Mitte sehr wenig. Die Farbe sagt es Euch. Rosa innen ist richtig, grau ist zu lange gegart. Den Unterschied kann ich nicht schmecken. Ich kann ihn sehen, und das Gesicht dessen, der isst, kann es auch. Rosa bringt ein Nicken ein. Grau bringt Höflichkeit ein, und das ist schlimmer." },
    [7828] = { "Seine Schuppen würden ein billiges Messer stumpf machen, also kauft ein gutes, bevor Ihr den Fisch kauft. Schuppt ihn draußen, wenn Ihr könnt. Die Schuppen fliegen überallhin und tauchen noch wochenlang auf. Dann eine heiße Pfanne und ein einziges Wenden. Das Fleisch zerfällt in saubere weiße Flocken und riecht nach kaltem Wasser und Salz. Es braucht nichts. Ich gebe ihm nichts, und meine Schüler lernen, dass nichts manchmal das Schwerste ist, was man geben kann." },
    [8238] = { "Deviatfische kommen aus den vergifteten Becken der Höhlen des Wehklagens, und wer immer sie vergiftet hat, wollte sie nicht köstlich machen. Ein wenig sind sie es. Gart den Fisch durch, mit milden Gewürzen, und gart ihn nicht zu kurz. Die Apotheker interessieren sich sehr dafür, was er mit den Lebenden anstellt. Ich habe zugesehen. Ich sage nur, dass es das einzige Gericht ist, das meine Kunden je zweimal gegessen haben, um zu sehen, was passiert." },
    [8604] = { "Ein Ei ist das Erste, was ich lehre, denn es verrät Euch alles durch seinen Geruch, lange bevor es Euch irgendetwas durch seinen Geschmack verrät. Wenn die Küche nach warmen Gewürzen riecht und nach sonst nichts, ist es fertig. Wenn sie nach etwas Schärferem riecht, fangt neu an, statt mit ihm zu streiten. Das Ei hat immer recht. Meine Schüler halten ein Ei für unter ihrer Würde. Ein Ei hat mehr von ihnen blamiert als jeder Eber." },
    [8607] = { "Kein Gewürz und keine Soße, nur Rauch und Zeit. Das ist Essen für Leute, die irgendwohin unterwegs sind. Schneidet das Fleisch längs der Faser und hängt es hoch über ein kleines Feuer aus grünem Holz, wo die Hitze es nie erreicht und der Rauch die ganze Arbeit tut. Am Morgen sollten sich die Streifen biegen, bevor sie brechen. Ich packe sie für die Todeswachen auf dem Weg zum Grabmal ein. Sie müssen nicht essen, und sie nehmen jede drei." },
    [9513] = { "Flitzdistel, in Quellwasser gezogen, bis es grüngolden wird, dann abgeseiht. Jeder Schurke in Undercity trinkt ihn vor der Arbeit, und Undercity hat sehr viele Schurken. Sie kommen zu seltsamen Stunden an meine Theke, sprechen leise und zahlen immer passend. Lasst ihn nicht zu lange ziehen. Er wird bitter, und die Schurken, die ihn bitter mögen, trinken ihn trotzdem und gehen ohne ein Wort." },
    [13028] = { "Ein Golddorn ergibt vier Tassen, was Euch sagt, wie kräftig er ist. Lasst ihn in Wasser ziehen, das gerade nicht mehr kocht, bis es die Farbe von altem Messing hat, und seiht ihn dann gründlich ab. Der Geruch ist scharf und hell, wie ein Schwert, das poliert wird. Jede Todeswache auf den Mauern trinkt ihn, und keine von ihnen braucht ihn. Sie können ihn nicht besser schmecken als ich. Ich glaube, sie mögen die Wärme der Tasse in ihren Händen. Ich habe nie gefragt." },
    [15853] = { "Ein schlichtes Steak aus der Flanke eines Wolfs, mit einer Prise Gewürz und nichts, wohinter man sich verstecken kann. Das macht es zu einer Prüfung. Bratet es schnell an, lasst es lange ruhen, schneidet es dünn quer zur Faser. Ich beurteile es nach seiner Farbe und nach dem Gesicht dessen, der es isst, denn anders kann ich es nicht. Ich lasse meine Schüler es kochen, bis sie beim Zischen der Pfanne nicht mehr zusammenzucken. Manche brauchen eine Woche. Einer brauchte ein Jahr." },
    [15855] = { "Die Lager im Schlingendorntal rösten Raptor in großen Stücken, und ich auch, denn Raptor ist mager, und ein großes Stück hält seine eigene Mitte saftig. Scharfe Gewürze außen, ein kräftiges Feuer, dann zieht ihn von der Hitze weg, damit er fertig gart. Der Geruch wechselt von Metall zu Rauch zu gerösteten Nüssen. Irgendwo bei den Nüssen nehmt ihn herunter. Der Raptor hat hart gekämpft. Lasst ihn nicht bei Tisch gewinnen." },
    [15856] = { "Rote Wölfe aus dem fernen Süden, fetter als die grauen im Silberwald, mit Rippen, die Zeit brauchen, bis ihr Fett schmilzt. Scharfe Gewürze und ein heißes Feuer, dann Geduld. Das Fett läuft klar, bevor es zu rauchen beginnt, und der Moment dazwischen ist der, den Ihr wollt. Die Todeswachen, die aus dem Süden zurückkehren, bringen sie in Tücher gewickelt mit herauf, als hätten sie einen Schatz gefunden. Für eine Köchin haben sie das." },
    [15861] = { "Tigerfleisch, Quellwasser und Äpfel, der Eintopf des Schlingendorntals. Bräunt zuerst das Fleisch, gebt dann das Wasser und die Äpfel hinzu und lasst ihn köcheln, bis die Frucht in der Brühe aufgegangen ist. Der Geruch wird süß, dann tief, dann wieder süß. Die zweite Süße heißt, dass er fertig ist. Trolle haben ihn mir beigebracht, Darkspear auf dem Weg an einen wärmeren Ort. Sie sagten, er schmecke nach Heimat. Ich habe ihnen geglaubt." },
    [15863] = { "Die Trolle des Sumpfes nennen dies eine Pastete und meinen es freundlich. Eigenartiges Fleisch und scharfe Gewürze, gegart, bis über nichts mehr Zweifel bestehen. Ich kann riechen, was das Fleisch war, und das ist mehr, als die Trolle können, und ich serviere es trotzdem. Gart es durch, und dann gart es noch einmal. Was immer es war, es hat eine lange Reise hinter sich, und es verdient ein entschlossenes Ende." },
    [15865] = { "Eigenartiges Fleisch, in zwergischem Starkbier geschmort, und für mich ist an keinem von beiden etwas eigenartig. Ich kann genau riechen, was das Fleisch war. Ich kann die Brauerei riechen, aus der das Starkbier kam, und was auf ihrem Boden verschüttet wurde. Hier unten, wo wir Geheimnissen von Berufs wegen nachschnüffeln, ist dieses Gericht eher eine Lebensbeichte. Gart ihn lange und sanft, und lasst ihn niemals kochen, sonst wird das Starkbier sauer, und das riecht Ihr bis zur Treppe. Schöpft den Schaum ab, während er köchelt. Das Starkbier macht das Fleisch dunkel und weich und gibt der Brühe eine Bitterkeit, die die Lebenden sehr zu mögen scheinen. Die Apotheker, die es besser wissen sollten, essen ihn in Mengen und weigern sich zu sagen, was ihrer Meinung nach darin ist. Ich habe aufgehört, es ihnen zu sagen. Sie genießen ihn mehr, wenn sie es nicht wissen, und das tun, glaube ich, alle." },
    [15906] = { "Eigenartiges Fleisch ist für mich nicht eigenartig. Ich kann genau riechen, was es war, und in den meisten Fällen sage ich es lieber nicht. Das Brachland hat mir dieses Gericht beigebracht, nicht Lordaeron, wo man nie etwas aß, das sich so heftig wehrte. Wie scharf dieses Chili ist, kann ich Euch nicht sagen. Ich kann Euch sagen, dass die gerösteten Gewürze mir in den Augen brennen, und das ist der einzige Teil davon, den ich noch spüre. Und der letzte Taure, der meines probiert hat, legte seinen Löffel sehr vorsichtig hin und bat mit einer Stimme, die ich noch nie von ihm gehört hatte, um Wasser. Stecht den Flammenbeutel an, bevor er hineinkommt, sonst platzt er von selbst. Macht es für Leute, die Ihr mögt, und warnt sie. Dann seht in ihre Gesichter. Das Gericht ist fertig, wenn sie aufhören zu reden." },
    [15910] = { "Die Kodos von Desolace sind schwerer als die des Brachlands, obwohl sie von sehr wenig leben, und ihr Fleisch ist das dichteste, das ich kenne. Die Tauren haben mir diesen Eintopf beigebracht, und ich habe nie etwas daran geändert, denn es gibt nichts zu ändern. Zwei Portionen schweres Kodofleisch, feine Gewürze und Quellwasser, und ein ganzer Tag über kleinem Feuer. Ihr werdet riechen, wie er sich wandelt: roh, dann grasig, dann tief und braun, wie ein Feld nach dem Regen. Irgendwann am Abend zerfällt das Fleisch bei der Berührung eines Löffels in Fäden. Das ist der Moment, und kein anderer. Ich mache ihn an den kältesten Tagen für die Todeswachen auf den Mauern darüber, und ich trage ihn selbst hinauf. Sie brauchen ihn nicht. Sie stellen sich trotzdem an, und sie sind sehr still, während sie essen." },
    [15915] = { "Zartes Krebsfleisch und eine Menge scharfer Gewürze, unablässig gerührt in einer Pfanne, so heiß, dass Ihr einen Schritt zurücktretet. Die Gewürze müssen in den Krebs hineingaren, nicht auf ihm sitzen. Wie scharf es ist, kann ich Euch nicht sagen. Ich kann Euch sagen, dass die Trolle es essen, ohne zu blinzeln, und die Orcs es essen, während sie so tun, als blinzelten sie nicht, und ich bediene beide mit derselben ernsten Miene." },
    [15933] = { "Ein einziges Riesenei macht einen ganzen Tisch satt, und in Undercity gilt als Tisch, wer gerade dem Herd am nächsten steht. Die Eier stammen von den großen Vögeln des Nordens, aus dem Teufelswald und aus Winterspring, heruntergebracht von Händlern, die gelernt haben, nicht zu sagen, wo sie sie gefunden haben. Schlagt das Ei mit feinen Gewürzen, bis es glatt und blass ist, gießt es dann in die breiteste Pfanne, die Ihr besitzt, bei mittlerer Hitze, und zieht die Ränder ein, sobald sie stocken. Der Geruch ist der Wegweiser: zuerst warm und rund, dann nussig an den Rändern. Nussig ist der Moment zum Zusammenklappen. Braun ist zu spät. Tragt es mit beiden Händen zum Tisch. Ich habe eine ganze Streife Todeswachen eines davon schweigend teilen sehen, mit großer Sorgfalt, als wäre es ein Schatz. Für einen Augenblick war es das. Dann baten sie um ein zweites, und das war das Schönste daran." },
    [15935] = { "Jeder neue Koch in Tirisfal macht dies, denn Fledermäuse gibt es überall, und viel anderes gibt es nicht. Ich habe mehr davon gemacht als von irgendeinem Gericht meines ersten Lebens. Ritzt die Haut des Flügels ein, legt ihn mit der Haut nach unten auf eine heiße Platte und lasst ihn in Ruhe. Er redet, während er gart. Wenn das Zischen zu einem Knistern wird, wendet ihn einmal und nie wieder. Serviert ihn dem, der noch Hunger hat. In Undercity gibt es immer jemanden." },
    [18238] = { "Fest und ölig, aus den warmen Gewässern vor Tanaris, und umso besser, je weniger Ihr tut. Eine heiße Pfanne, ein einziges Wenden. Der Geruch, wenn er fertig ist, ist sauber und hell, wie eine Meeresbrise, die die Docks noch nicht erreicht hat. Meine Schüler wollen Dinge hinzufügen. Ich nehme ihnen das Gewürzglas weg und gebe es zurück, wenn der Fisch gegessen ist. Die meisten fragen nie wieder danach." },
    [18239] = { "Ein großer, reichhaltiger Fisch aus dem warmen Süden, in Steaks geschnitten, die dick genug sind, um wie Fleisch zu ruhen. Feine Gewürze runden die Fülle ab, ohne sie zu verbergen. Bratet die Steaks scharf an, lasst sie ruhen, serviert sie. Der Geruch ist so reichhaltig, dass er fast süß ist, und er trägt weit. Wenn ich Machtfisch koche, bildet sich die Schlange an meiner Theke, bevor der Fisch fertig ist. So früh bildet sie sich nie für etwas, worauf ich stolz bin." },
    [18240] = { "Ein Augenblick oder eine Stunde, nichts dazwischen. Ich wähle den Augenblick. Ritzt den Kalmar kreuzweise ein, reibt ein wenig feine Gewürze in die Schnitte und legt ihn auf den heißesten Grill, den Ihr habt. Er rollt sich ein, als wäre er überrascht. Wenn die Ränder verkohlen, ist er fertig. Der Geruch ist süß und rauchig, und er zieht die Kunden von der Straße herein wie an einem Seil." },
    [18241] = { "Die Rotkieme braucht nichts als eine heiße Pfanne. Legt das Filet mit der Haut nach unten und wartet, bis es sich von selbst löst. Das ist die ganze Lektion, und die meisten Schüler brauchen einen Monat, um sie zu lernen, denn Warten ist schwerer als Tun. Der Geruch geht von roh zu süß, und die Ränder gehen von glasig zu weiß. Hebt es dann heraus. Es hat Euch alles gesagt, was es weiß." },
    [18242] = { "Heiß und nah geräuchert, sodass der Fisch gart, während er räuchert. Reibt den Sommerbarsch mit scharfen Gewürzen ein und hängt ihn knapp über ein rauchiges Feuer. Behaltet das Fleisch im Auge: Wenn es von glasig zu weiß wechselt, nehmt ihn herunter. So geräucherter Barsch hält sich tagelang. Ich packe ihn für Reisende ein, die den Zeppelin nehmen. Sie sind immer hungrig und immer spät dran, und sie essen ihn, bevor der Zeppelin den Turm verlässt." },
    [18243] = { "Ein Schnapper, nachts gefangen, und Quellwasser, und sonst nichts. Lasst den Fisch sanft köcheln, bis das Fleisch von den Gräten fällt, und hebt dann die Gräten vorsichtig heraus. Die Brühe sollte klar genug sein, um hindurchzulesen. Sie riecht nach sehr wenig, und darum geht es: eine saubere, stille Suppe für Leute, die einen lauten Tag hatten. Ich mache sie mir selbst am Ende des Abends, und es macht mir nichts aus, dass ich sie nicht schmecken kann." },
    [18244] = { "Wasser, das nie ganz kocht, für einen Fisch, der unter allem Härteren zerfallen würde. Bringt es zum Zittern, lasst den Lachs hinein und lasst ihn in Ruhe. Ihr werdet sehen, wie er von leuchtend zu blass wechselt, als würde er rückwärts erröten. Hebt ihn dann heraus. Das Pochieren ist das Sanfteste, was ich in einer Küche tue, und das, was meine Schüler am schwersten finden, weil so lange nichts geschieht." },
    [18245] = { "Dunkelklauenhummer in Quellwasser, und das ist alles. Lasst den Hummer im Ganzen hinein und hebt ihn heraus, sobald die Schale rot wird. Löst das Fleisch aus der Schale und erwärmt es in der Brühe. Kocht ihn niemals zweimal. Der Geruch eines Hummers, der zu lange gart, ist scharf und unverkennbar, wie heißes Kupfer, und wenn Ihr ihn einmal gerochen habt, werdet Ihr es nie wieder geschehen lassen. Ich habe es einmal geschehen lassen. Das hat gereicht." },
    [18246] = { "Ein Machtfisch ist groß genug, um wie Rind in Steaks geschnitten zu werden, und er sollte wie Rind gegart werden. Scharfe Gewürze, um ihn zu wecken, feine Gewürze, um ihn zu beruhigen, ein scharfes Anbraten auf beiden Seiten und eine lange Ruhe. Der Geruch ist zugleich der des Meeres und einer Schmiede. Ich serviere ihn den Todeswachen in den Nächten vor einer langen Streife. Sie sagen nichts, und das sagen Todeswachen, wenn etwas gut ist." },
    [18247] = { "Ein ganzer Lachs aus den kalten Flüssen, mit feinen Gewürzen in einem mäßigen Ofen gebacken. Im Ganzen, weil die Haut das Fleisch saftig hält wie ein Deckel auf einem Topf. Wenn das Auge weiß wird und die Flosse sich bei einer Berührung löst, ist er fertig. Die Küche riecht nach Flüssen und warmen Gewürzen, und die Apotheker kommen herunter, um sich Dinge zu leihen, die sie nicht brauchen, und gehen mit einem Teller." },
    [20626] = { "Eine Muschelsuppe der Goblins aus Tanaris: scharfes Muschelfleisch, scharfe Gewürze und eiskalte Milch, zusammen erwärmt, ohne je zu kochen. Die Goblins essen sie kochend heiß, und das sagt Euch alles über Goblins. Haltet die Hitze niedrig und behaltet den Dampf im Auge. Wenn er nach Meer und warmen Gewürzen riecht und noch nicht nach angebrannter Milch, schöpft sie aus. Der Goblin, der sie verkauft, hat immer nur ein Exemplar vorrätig. Ich habe es gekauft, und jetzt gibt es zwei." },
    [20916] = { "Ein kalter Bergfisch mit einem silbernen Kopf und dem Temperament eines Kämpfers. Bratet sie im Ganzen, mit Haut, in einer heißen Pfanne und begießt sie mit ihrem eigenen Fett. Wenn die Haut Blasen wirft und das Auge weiß wird, ist sie fertig. Lasst den Kopf dran. Meine Schüler fragen, warum. Ich sage ihnen, der Fisch habe hart gearbeitet, um ihn zu behalten, und das Mindeste, was wir tun können, ist, ihn mit an den Tisch kommen zu lassen." },
    [21143] = { "Der Winterhauch in Lordaeron roch nach diesen Kuchen, aus jeder Küche der Straße zugleich, oder ich glaube jedenfalls, dass er das tat. Ich erinnere mich so deutlich an den Duft, dass ich ihn manchmal im Sommer in Undercity zu riechen meine, und das kann nicht stimmen. Festtagsgewürze und ein Ei, miteinander verknetet und gebacken, bis die Ränder dunkel werden und die Mitte noch nachgibt. Beim Abkühlen werden sie fest. Ich backe sie jeden Winterhauch für die Kinder der Zeppelinmannschaften. Sie fragen nicht, warum ich so viele backe." },
    [21144] = { "Winterhauch, und irgendjemandes Onkel, der in einer großen Schüssel Eierflip macht, zu stark, jedes Jahr. Sein Gesicht sehe ich nicht, aber ich höre ihn singen. Ein Ei, eiskalte Milch, Festtagsgeister und Festtagsgewürze, geschlagen, bis alles blass und dick ist. Die Geister kommen zuletzt hinein und mit Zurückhaltung, die noch kein Onkel je gezeigt hat. Es riecht nach Muskat und warmem Holz und ein wenig nach Ärger. Serviert ihn kalt und behaltet die Schüssel im Auge." },
    [21175] = { "An Spinnen mangelt es Undercity nie. Weißes Spinnenfleisch ist süß und zart und verlangt überhaupt kein Gewürz, was eine Gnade ist in einer Stadt, die nach allem riecht. Presst es in Hüllen, fest genug, um zu halten, und dünn genug, um aufzuspringen. Horcht in der Pfanne auf das Knacken. Es ist das befriedigendste Geräusch in meiner Küche, und meine Schüler lernen, darauf zu warten." },
    [22480] = { "Die Wölfe der kalten Orte leben langsam und behalten ihr Fett, und ihr Fleisch ist das beste aller Wölfe. Feine Gewürze, ein kurzes, heißes Anbraten, eine lange Ruhe. Ihr werdet riechen, wann es so weit ist: Die Gewürze werden warm, und das Fleisch wird süß, wie ein Laib frisch aus dem Ofen. Meine Schüler schwören, sie schmeckten den Unterschied vom ersten Bissen an, und ich glaube ihnen, denn sie hören auf zu reden. Ein Koch, der gegen hundert sehnige Wölfe gekämpft hat, verdient diesen hier. Ich serviere ihn meinen besten Schülern." },
    [22761] = { "Das Rezept stammt von einem Wichtel in den Ruinen von Düsterbruch, der jeden, der es haben will, auf eine lange und dumme Hetzjagd schickt. Einer meiner Schüler hat diese Jagd gemacht und kam mit dem Rezept zurück, mit zwei neuen Narben und mit sehr viel zu sagen über Wichtel. Die Runn Tum Knolle wächst im Schatten dieser Ruinen, und sie ist die feinste Wurzel, die ich kenne, erdig und süß. Schält sie, schneidet sie in dicke Scheiben und röstet sie langsam mit feinen Gewürzen, bis die Ränder dunkel werden und die Mitte unter einer Gabel nachgibt. Ihr werdet riechen, wann sie richtig ist: wie Maronen an einer Straßenecke im Winter. Das ist nicht meine Erinnerung, es ist die meines Schülers, der es so gut beschrieben hat, dass ich sie mir geliehen habe. Die Todeswachen mögen sie, weil sie satt macht. Die Lebenden mögen sie, weil sie, wie sie mir sagen, nach einem sicheren Ort schmeckt. Ich mache sehr viel davon." },
    [24418] = { "Doppelt so viel Krokilisk, feine Gewürze und ein Eintopf, in dem ein Löffel stehen kann. Rührt oft vom Boden her um, denn ein so dicker Eintopf setzt an und verbrennt, wo Ihr es nicht sehen könnt, und der Geruch verrät Euch erst, wenn es zu spät ist. Die Soldaten der Marschen essen ihn aus Blechschüsseln im Regen, sagt man mir. Meine Todeswachen essen ihn aus Blechschüsseln im Trockenen. Blechschüsseln sind überall gleich." },
    [24801] = { "Der Zirkel des Cenarius lehrt dies in Silithus jenen, die sich in der Wüste bewährt haben, und die Soldaten der Horde brachten es zwischen ihren Narben mit zurück. Sandwurmfleisch ist dicht und blass und voller Sand. Wascht es, bis das Wasser klar abläuft, hackt es fein mit feinen Gewürzen und rollt es zu kleinen Knödeln, fest gedrückt, damit sie im Rauch zusammenhalten. Dann räuchert sie langsam über einem kleinen Feuer. Der Rauch würzt die Außenseite, während der Dampf die Mitte gart, und der Geruch wandert von roh zu süß zu etwas wie geröstetem Getreide. Wenn er beim Getreide ankommt, sind sie fertig. Wie sie schmecken, kann ich Euch nicht sagen. Ich kann Euch sagen, dass ein Soldat, der in dieser Wüste drei Freunde verloren hatte, in meiner Küche einen Teller davon aß und weinte, und dann um das Rezept bat, und ich gab es ihm." },
    [25659] = { "Ein Goblin in Gadgetzan gart Chimaerok mit Raketentreibstoff, und die Reisenden der Horde tragen das Rezept wie eine Mutprobe nach Hause. Meines kam von einem Tauren, der seine Augenbrauen verloren und seinen Appetit behalten hatte. Chimaeroklenden sind ein weiter Weg für ein Stück Fleisch, die Inseln vor Feralas, und sie sind jeden Schritt wert. Tiefsteinsalz, scharfe Gewürze und der Goblin-Raketentreibstoff, der aufs Feuer kommt, niemals ins Essen. Tretet weiter zurück, als höflich scheint. Die Stichflamme dauert einen Atemzug und hinterlässt eine Kruste, die keine ehrliche Kohle machen könnte. Der Geruch füllt das ganze Apothekarium, und die Apotheker kommen aus ihren Räumen, um sich zu beschweren, und bleiben zum Essen. Ich frage nicht, was sie davon halten. Ich zähle die Teller." },
    [25704] = { "Weisenfische kommen aus den Seen von Hillsbrad, wohin meine Familie im Sommer fuhr, oder wohin wir immer sagten, dass wir fahren würden. Der Fisch riecht nach dem Salbei an den Ufern, und der Rauch verstärkt diesen Duft. Beim Geruch bin ich mir sicher. Bei den Sommern weniger. Wenig Rauch, eine Prise milder Gewürze und ein Nachmittag. Wenn das Fleisch golden wird und nach Kräutern und Holzrauch riecht, ist er fertig." },
    [25954] = { "Der große Weisenfisch, fett geworden am Salbei seines Sees, mit scharfen Gewürzen, die ihn wecken. Bratet das Filet mit der Haut nach unten, bis die Haut knistert, und wendet es dann für einen Atemzug. Der Geruch ist das Supreme daran: grün und warm und pfeffrig, alles zugleich. Ich mache diesen, wenn die Küche nach etwas anderem riechen soll als nach der Stadt darüber, und das ist, wenn ich ehrlich bin, an den meisten Tagen." },
    [470359] = { "Weihwasser aus Stratholme, das mir die Apotheker mit ernster Miene reichten. Ich war einmal in Stratholme, lebendig, für einen Markt oder eine Hochzeit, und ich erinnere mich an die Glocken und das Brot und an nichts sonst. Jetzt macht sein Wasser eine Cremesuppe. Dunkelklauenhummer, darin geköchelt, bis die Schale rot wird, dann glatt gesiebt. Das Wasser ist sehr weich und sehr sauber, und es verbrennt mich nicht. Es lässt den Hummer sprechen. Ich höre zu." },
    [470370] = { "Die Expedition in Silithus verkauft dies an Soldaten, die Essen brauchen, das sich im Sand hält. Rotkieme, langsam geräuchert, bis sie trocken genug zum Tragen und noch zart genug zum Essen ist. Kein Gewürz. Rauch und Zeit tun die Arbeit. Ich habe es von einem Apotheker gelernt, der mit diesem Rezept und sehr wenig sonst aus der Wüste zurückkam. Er sagte, es sei das Einzige dort gewesen, was nicht versucht habe, ihn umzubringen." },
    [1225758] = { "Tiger, das meint der Name, dick geschnitten und eine Stunde vor dem Garen mit Weihsalz eingerieben. Tiger ist ein fleißiges Fleisch, und das Salz beruhigt es. Dann ein heißes Eisen, ein kurzes Anbraten und eine lange Ruhe. Ihr werdet hören, wie es sich auf dem Brett entspannt, ein leises Setzen, wie ein Hund, der sich hinlegt. Dann schneidet Ihr. Nicht vorher. Ein Tiger, der sich nicht gesetzt hat, setzt sich auch bei Tisch nicht." },
    [1225759] = { "Weihsalz, aus den Kirchen der Lebenden, was mich zum Lachen brachte, als ich zum ersten Mal einen Beutel davon in der Hand hielt. Es ist gutes Salz. Das Licht hat in einer Küche nichts gegen mich. Reibt es in die Flanke des roten Wolfs und lasst sie eine Stunde liegen, dann gart sie schnell. Das Salz zieht das Wasser aus dem Fleisch und macht es fester. Es verbrennt mich nicht, bevor Ihr fragt. Meine Schüler fragen immer." },
    [1225760] = { "Zwei Rieseneier und Weihsalz. Man hat mich gewarnt, es würde mich verbrennen, und das tut es nicht. Gart es langsam, damit der Dotter leuchtend bleibt wie der Morgen. Der Geruch ist sauber und schlicht, Ei und Salz und die Pfanne. Ich koche es zu der Stunde, die die Lebenden Morgendämmerung nennen, was hier unten nichts bedeutet, aus einer Gewohnheit, an deren Entstehen ich mich nicht erinnere. Jemand kommt immer dafür herein. Jemand kommt immer." },
    [1225762] = { "Zwölf Tüpfelgelbschwänze, drei Steinschuppenkabeljaue, vier Portionen Raptorfleisch und erlesene Gewürze, ausgelegt auf dem größten Brett der Küche. Der Kabeljau kommt zuerst, weil er dick ist. Der Raptor brät und ruht, während der Fisch gart. Die Gelbschwänze kommen zuletzt, weil sie schnell sind, und in dem Augenblick, in dem sich ihre Haut vom Grill löst, sind sie fertig. Der Geruch eines Fischfestmahls ist eine aufkommende Flut: zuerst das Meer, dann der Rauch, dann die Gewürze. Wenn die Gewürze ankommen, fangt an zu tragen. Ich habe es für die Zeppelinmannschaften am Ende einer langen Saison gemacht, und die Goblins, die nicht sentimental sind, setzten sich an meine Theke und aßen eine Stunde lang, ohne ein einziges Mal Geld zu erwähnen. Das ist das einzige Mal, dass ich einen Goblin habe vergessen sehen zu feilschen. Es war das Festmahl, nicht ich." },
    [1225763] = { "Ein Bankett ist sehr viel Arbeit für einen einzigen Abend, und dieses ist mehr als die meisten: zwölf Dunkelklauenhummer, vier Portionen Schildkrötenfleisch, drei Bussardflügel und erlesene Gewürze, die vor allem im Preis erlesen sind. Die Schildkröte schmort am längsten, also beginnt sie zuerst. Der Bussard brät, während die Schildkröte schmort. Die Hummer kommen zuletzt, portionsweise pochiert und herausgehoben, sobald ihre Schalen rot werden, bevor der Geruch zu Kupfer umschlägt. Alles muss zusammen auf den Tisch kommen, und Ihr wisst, dass es so weit ist, wenn die Halle zugleich nach Meer, Wald und Herd riecht. Ich habe es zweimal gekocht, für die Offiziere der Dunklen Fürstin, die nichts sagten und alles aßen. Beim zweiten Mal kam einer von ihnen danach in die Küche herunter, um mir zu sagen, es sei sehr gut gewesen. Er hatte keinen Hummer mehr gegessen, seit er noch lebte. Er erinnerte sich, wie einer sein sollte." },
    [1229737] = { "Vor dem Essen das Feuer. Einfaches Holz, locker geschichtet, damit die Luft hindurchziehen kann, unten angezündet und dann in Ruhe gelassen. Ihr werdet hören, wann es so weit ist: Das Knistern legt sich zu einem tiefen Summen, und die Flammen sinken zu Glut zusammen. Kocht auf der Glut, niemals auf den Flammen. Das lehre ich zuerst, noch vor dem Wolf, denn ein Koch ohne Feuer ist ein Gast, und Gäste behalte ich nicht in meiner Küche." },
    [1247741] = { "Ein Rezept ohne Verkäufer, bisher, für einen Fisch, den ich nie gesehen habe. Man sagt mir, der Rückenflossenheilbutt sei breit und weiß und am Rücken bewaffnet, und so sagen Fische, dass sie lieber nicht gegessen werden möchten. Gart ihn in einem dicken Stück, sanft, bis die Flocken eben anfangen auseinanderzugehen. Ich schreibe das auf, damit der erste Koch, der einen fängt, einen Anfang hat. Erzählt mir, wie er gerochen hat." },
    [1249957] = { "Friedensblume, in Quellwasser gezogen, bis das Wasser die Farbe von Stroh annimmt. Lasst es nicht kochen, sonst riecht es nach Heu und nach sonst nichts. Lasst es ziehen, und es riecht nach dem Rand eines Feldes am Abend, hinter einem Haus, das ich nicht mehr zuordnen kann, und das ist noch immer der schönste Geruch, den ich kenne. Die Trolle der Frostmane brauen ihn, sagt das Rezept. Ich mache ihn für die Apotheker, die Ruhe nötiger haben als irgendjemand sonst und weniger davon bekommen." },
    [1249958] = { "Maguskönigskraut, in warmer Milch gezogen, bis die Milch einen leichten violetten Schimmer bekommt. In Lordaeron wurde er bei Hofe serviert, so sagten wir jedenfalls in den Küchen, so wie Küchen eben Dinge über den Hof sagen. Ich habe nie einen König ihn trinken sehen. Ich bin nicht sicher, ob ich je einen König gesehen habe. Erwärmt die Milch sanft und lasst sie nie kochen, sonst bildet sie eine Haut. Eine Haut auf königlichem Tee hätte eine Köchin einst ihre Stelle gekostet. Heute kostet sie sie nichts, und ich hebe sie trotzdem ab." },
    [1249959] = { "Lebenswurz, gewaschen und in Scheiben geschnitten, in warmem Melonensaft gezogen, bis der Saft dunkel wird und zugleich nach Erde und nach Sommer riecht. Seiht ihn sorgfältig ab, denn eine Wurzel, die zu lange bleibt, lässt den Tee nach dem Boden schmecken. Ich kann es nicht schmecken, aber ich kann den Boden kommen riechen, eine schwere, nasse Note unter der Süße. Hebt die Wurzel heraus, bevor sie kommt. Die Lebenden bemerken es. Sie bemerken immer die Dinge, die ich nicht kann." },
    [1249960] = { "Süßer Nektar und Blassblatt, ein Tee für die Verwundeten, obwohl Blassblatt das ist, was Schurken kauen, um aus dem Blick zu verschwinden. Vielleicht möchten die Verwundeten auch aus dem Blick verschwinden. Erwärmt den Nektar, bis er dampft, lasst das Blassblatt ziehen und seiht es ab, bevor es bitter wird. Man hat mir dieses Rezept nie verkauft. Ich habe es nach einer Beschreibung gemacht, für die Patienten der Apotheker, die sich nicht beschwert haben, aber das können sie selten." },
    [1249961] = { "Sonnengras, in Mondbeerensaft gezogen, bis das Getränk golden wird. Es riecht nach Heu am Nachmittag und nach einer warmen Mauer in der Sonne. In Undercity gibt es keine Sonne. Ich mache diesen Tee, wenn meine Schüler still und blass geworden sind und anfangen zu vergessen, wie es an der Oberfläche ist, und ich gebe ihn ihnen in die Hände, und er erinnert sie. Das steht nicht im Rezept. Es sollte." },
    [1249962] = { "Bergsilberweisling in Trichterwindentau, zwei Dinge, die schwer zu finden sind, zusammen zu einem Tee gezogen, der nach kalter Luft und Stein riecht. Erwärmt den Tau sanft, lasst den Silberweisling ziehen, bis das Getränk blass wird, und seiht es ab. Die Lebenden sagen, er schmecke nach nicht viel, und die Apotheker glauben, er schärfe den Verstand. Ich glaube, er gibt ihnen einen Vorwand, für die Dauer einer Tasse mit der Arbeit aufzuhören, und ich widerspreche keinem von beiden." },
    [1249963] = { "Quellwasser, milde Gewürze und ein kleiner Giftbeutel, zerdrückt und durchgeseiht, sodass nur die Schärfe bleibt. Die Apotheker haben meine erste Mischung geprüft. Das Urteil: unbedenklich für die Lebenden, gesprochen mit einer Enttäuschung, zu der ich mich lieber nicht geäußert habe. Schüttelt ihn kräftig und serviert ihn kalt. Die Lebenden sagen, er brenne auf der Zunge. Ich glaube ihnen, und ich sehe zu, wie sie nach einem zweiten Glas greifen." },
    [1249964] = { "Eiskalte Milch, milde Gewürze und Spinnensekret, geschüttelt, bis das Sekret aufgibt und sich untermischt. Er riecht schwach nach Mandeln und stark nach Spinne. Serviert ihn sofort. Wenn er steht, trennt er sich, und ein getrennter schleimiger Smoothie ist ein Anblick, den niemand ertragen sollte. Die Apotheker trinken ihn krugweise bei der Arbeit, und das sagt etwas über die Apotheker, und ich sage nicht, was." },
    [1249965] = { "Den Namen versuche ich gar nicht erst. Melonensaft, scharfe Gewürze und eine Murlocflosse, geschüttelt, bis die Flosse ihren Geschmack an den Saft abgibt. Er riecht nach einer Melone, die am Meer war und verändert zurückkam. Die Murlocs im Silberwald wären geehrt, glaube ich, oder wütend. Bei Murlocs ist das schwer zu sagen, und der Lärm ist derselbe. Ich serviere ihn den Mutigen, und den sehr Gelangweilten." },
    [1249966] = { "Süßer Nektar, scharfe Gewürze und ein großer Fangzahn, zu Pulver gemahlen. Der Zahn macht das Getränk kreidig und dick, wie Milch, die zu lange in der Sonne stand und es sich dort bequem gemacht hat. Seiht ihn gut ab, zweimal, denn Grieß in einem Getränk verzeiht niemand. Die Lebenden, die vom Kämpfen leben, trinken ihn morgens. Die Todeswachen, die vom Kämpfen leben und nicht leben, trinken ihn aus Solidarität." },
    [1249967] = { "Mondbeerensaft, feine Gewürze und ein kleiner Flammenbeutel, angestochen und ins Glas gedrückt. Der Flammenbeutel sorgt für die Hitze und die Gewürze für die Entschuldigung. Schüttelt ihn und trinkt ihn schnell. Wie scharf er ist, kann ich Euch nicht sagen. Ich kann Euch sagen, dass ich einmal einem Orc zugesehen habe, der einen trank und dann sehr lange sehr still dastand und an die Decke starrte, als hätte sie ihn beleidigt." },
    [1249968] = { "Trichterwindentau, eine große Menge feiner Gewürze und eine tückische Klaue, fein gemahlen. Die Klaue gibt ihm eine dunkle, bittere Kante, die die Gewürze nicht ganz glätten können. Er riecht nach zerdrückten Blumen und nach etwas, das Euch gern beißen würde. Serviert ihn kalt. Die jungen Todeswachen trinken ihn auf eine Wette hin. Die alten trinken ihn, weil sie aufgehört haben, Wetten anzunehmen, und mögen ihn trotzdem." },
    [1250142] = { "Kleine Runden aus gehacktem Hirsch und scharfen Gewürzen, einmal gedrückt und schnell gebraten. Drückt sie zweimal, und der Saft läuft in die Pfanne statt zum Gast. Die Lebenden mögen Essen, das sie mit einer Hand essen können. Ich habe Hafenarbeiter am Zeppelinturm zwischen zwei Ankünften ein Dutzend davon essen und ohne ein Wort wieder an die Arbeit gehen sehen. Das ist die Kritik, die zählt." },
    [1250143] = { "Bussardflügel, entbeint und flach geklopft, um feine Gewürze gerollt und gebunden. Es ist langsame, fummelige Arbeit, und ich gebe sie Schülern, die stolz auf ihr Messer sind und es zeigen wollen. Röstet ihn sanft und schneidet ihn in Scheiben. Die Spirale darin verrät mir alles über den Koch, der ihn gerollt hat. Eine enge Spirale, eine sorgfältige Hand. Eine lockere, jemand, der ans Mittagessen gedacht hat." },
    [1250144] = { "Ein Eintopf armer Bauern aus klein geschnittenem Fleisch, lange und langsam gegart. In Lordaeron war es Rind, wenn es Rind gab, oder ich glaube, dass es so war. Hier unten ist es Fledermaus. Hackt die Flügel fein, gebt die feinen Gewürze dazu und gebt ihm für einen Abend ein kleines Feuer, bis die Sehnen weich werden und die Küche nach Nelken riecht und nach etwas wie Zuhause. Meine Schüler nennen es Fledermausbrei. Ich nenne es Abendessen." },
    [1250145] = { "Schildkröte, geschmort und nicht passiert, ein Bauerneintopf statt einer Suppe für einen Fürsten. Wir haben ihn in Lordaeron an einem Fluss gemacht, dessen bin ich mir fast sicher, auch wenn ich Euch nicht sagen könnte, an welchem. Drei Portionen Schildkrötenfleisch und reichlich feine Gewürze, geköchelt, bis das Fleisch zerfällt. Lasst ihn dick. Der Biss ist der Sinn, und der Geruch, rund und warm und langsam, ist der Grund, warum die Leute an der Theke bleiben, nachdem sie fertig sind. Ich habe aufgehört, sie zum Gehen aufzufordern. Sie gehen, wenn die Schüssel leer ist, und nicht vorher." },
    [1250146] = { "Es ist kein Pfeffer darin, was immer der Name sagt, nur die Flanke des roten Wolfs und feine Gewürze, die die Arbeit des Pfeffers gut genug tun. Bratet die Flanke scharf an, lasst sie ruhen, während die Pfanne abkühlt, und gießt dann ihre Säfte wieder darüber. Der Geruch, wenn die Säfte wieder auf das heiße Fleisch treffen, ist der ganze Sinn des Gerichts. Ich serviere es den Apothekern, wenn ich etwas von ihnen will, und es wirkt." },
    [1250147] = { "Dünne Scheiben Großbärenfleisch, mit feinen Gewürzen geschichtet und langsam geröstet, bis sich die Schichten zu einer einzigen zusammenpressen. Schneidet das Fleisch kalt, sonst reißt es. Der Geruch, wenn es fertig ist, ist das Beste daran, dunkel und süß und nah an verbranntem Zucker. Mit Geschnetzeltem hat es nichts zu tun, und niemand, den ich gefragt habe, weiß, warum es so heißt. Wer es benannt hat, wollte angeben. Wer es zuerst gekocht hat, nicht." },
    [1250148] = { "Hirsch, tief mit feinen Gewürzen eingerieben und auf einem sehr heißen Eisen angebraten, sofort serviert, solange es noch dampft. Der Dampf trägt den Geruch, und der Geruch ist die halbe Mahlzeit für jeden, der schmecken kann, und die ganze für mich. Lasst es nicht warten. Ein Steak, das aufhört zu dampfen, hat angefangen abzukühlen, und ein kaltes Steak ist ein Versprechen, das jemand auf dem Weg aus der Küche gebrochen hat." },
    [1250149] = { "Tiger und feine Gewürze, das heißeste Feuer, das Ihr machen könnt, die kürzeste Zeit, die Ihr ertragt. Der Name ist der eines Jägers. Die Methode ist die eines Kochs. Schnell zuschlagen, dann lange ruhen, und beim Ruhen scheitern alle, denn der Geruch ist wunderbar und die Gabel liegt gleich daneben. Ich lasse meine Schüler auf ihren Händen sitzen. Beim ersten Mal meine ich es ernst." },
    [1250150] = { "Ein Rezept, das ich gelesen habe, das mir aber nie verkauft wurde, und das macht mich misstrauisch. Die Rippchen garen bei niedriger Hitze, bis das Fleisch den Knochen loslässt, dann über einer heftigen Flamme, damit eine Kruste aus scharfen Gewürzen fest wird, und davon gibt es eine Menge. Allein der Rauch hat mir die Augen tränen lassen. Wie scharf sie sind, kann ich Euch nicht sagen. Ich kann Euch sagen, dass niemand, dem ich sie vorgesetzt habe, nach mehr Gewürz gefragt hat." },
    [1250151] = { "Das zäheste Stück vom zähesten Tier, und der Grund, warum ein Koch lernt, ein Feuer klein zu halten. Reibt die Brust mit scharfen Gewürzen ein und lasst sie einen ganzen Tag lang garen, bis sie unter einer Gabel nachgibt wie nasses Brot. Ihr könnt sie nicht drängen. Ihr könnt ihr nur zusehen und riechen, wie sie sich verändert, von rohem Eisen zu Rauch zu etwas Vollem und Dunklem. Wenn sie riecht wie ein Winterabend, ist sie fertig." },
    [1250152] = { "Raptor, den größten Teil eines Tages über dem kleinsten Feuer gegart, das ich halten kann, mit einer Menge feiner Gewürze, bis er bei der Berührung einer Gabel zerfällt. Zerpflückt ihn mit zwei Gabeln, niemals mit einem Messer. Die Todeswachen lieben ihn, weil er sich hält, und weil man ihn im Gehen aus einer Schüssel essen kann. Prähistorisch nennt er sich. Das sind auch die Tischmanieren mancher meiner Schüler." },
    [1250153] = { "Dünne Scheiben Raptor, um scharfe Gewürze gerollt und mit Schnur gebunden. Die Rollen garen von außen nach innen, also haltet die äußere Lage dünn. Bräunt sie auf jeder Seite, senkt dann das Feuer und lasst sie in Ruhe. Wenn die Schnur dunkel wird und nach verbranntem Heu riecht, schneidet sie ab, bevor jemand sie sieht. Ein Gast verzeiht sehr vieles, aber keine Schnur. Das habe ich von einem Gast gelernt." },
    [1250154] = { "Vorher und nachher gewürzt, denn Raptor ist mager, und die erste Schicht gart weg. Ich habe gelernt, den Moment zwischen den beiden zu riechen. Wenn die Scheiben aufhören zu zischen und anfangen zu ticken, wie eine Pfanne, die abkühlt, nehmt sie heraus und würzt sie noch einmal, solange sie heiß genug sind, um es aufzusaugen. Meine Schüler vergessen immer die zweite Schicht. Das Gericht verrät sie. Es riecht nach einem halben Rezept." },
    [1250155] = { "Zwei Rieseneier und scharfe Gewürze, bei kleiner Hitze gerührt, bis sie zu weichen Flocken stocken. Es dauert lange und braucht eine ruhige Hand, und es riecht die ganze Zeit nach etwas Vollem und Warmem, obwohl nichts in der Pfanne ist als Ei und Gewürz. Wenn der Geruch schärfer wird, hört auf. Die Eier sind kurz davor, zu fest zu werden. Ich gebe sie den Todeswachen nach der Nachtwache, und sie essen sie im Stehen an der Theke, noch in ihrer Rüstung." },
    [1250156] = { "Ein Raptorei ist so groß wie meine beiden Fäuste und riecht, wenn man es aufschlägt, schwach nach dem Sumpf, durch den seine Mutter gelaufen ist. Die Gewürze sind da, um diesem Geruch zu antworten, und es sind viele. Schlagt das Ei, würzt es und gart es in kleinen Runden auf einem heißen Stein. Die Runden blähen sich, wenn sie fertig sind. Meine Schüler essen sie, bevor ich sie zählen kann, und das sagt mir, dass das Rezept funktioniert." },
    [1250157] = { "Ein Ei und eine große Menge milder Gewürze, mehr, als vernünftig scheint, nach einem Rezept, das in einem Kondornest im Rotkammgebirge gefunden wurde. Ich habe es so gemacht, wie es geschrieben steht. Es riecht nach Morgen und nach einem Gewürzmarkt, und nach einer Küche mit einem Steinboden, die ich fast zuordnen kann. Schlagt das Ei, bis es nur noch eine Farbe hat, gießt es in eine heiße Pfanne und zieht die Ränder ein, sobald sie stocken. Klappt es weich zusammen. Die Lebenden, die es essen, sagen, es wecke sie auf. Die Todeswachen essen es, um sich daran zu erinnern, was ein Morgen einmal war." },
    [1250158] = { "Es ist keine Nudel darin, was immer der Name verspricht. Es gibt scharfes Muschelfleisch, eine Menge davon, in lange Bänder geschnitten und in feinen Gewürzen geschwenkt. Gart es einen Augenblick in einer heißen Pfanne und serviert es sofort, verheddert. Es isst sich wie Nudeln und riecht wie das Meer. Ich weiß nicht, wer es erfunden hat. Ich vermute, ein Koch, der kein Mehl und reichlich Muscheln hatte und sich nicht beschwert hat." },
    [1252566] = { "Ein kleiner, leuchtender Fisch mit einem lächerlichen Namen. Das Rezept taucht im Rotkammgebirge in den Bündeln von Kreaturen auf, die nicht kochen, was heißt, dass jemand, der gekocht hat, es dort verloren hat. Eine Prise milder Gewürze, eine heiße Pfanne, ein Augenblick. Der Geruch ist süß und flüchtig, wie Obst. Ich koche ihn, wenn die Zeppelinmannschaften ihre Kinder mit herunterbringen, denn der Name bringt sie zum Lachen, und Lachen ist hier unten nicht häufig genug." },
    [1255241] = { "Eine verderbte Blume, von den Druiden gereinigt, sodass sie nicht mehr tut, was solche Blumen tun. Ich halte trotzdem Abstand zu ihr, aus Gewohnheit. Hirschfleisch und ein Riesenei geben dem Eintopf seine Kraft, das Ei am Ende hineingeschlagen, damit die Brühe seidig wird. Er riecht nach grünen Dingen und warmer Brühe und, ganz schwach, nach etwas Verbranntem, das nicht mehr da ist. Ich koche ihn für jene, die aus dem Teufelswald zurückkommen und aussehen, als wäre der Wald mit ihnen gekommen." },
    [1262978] = { "Cookie ist der Murloc, der in den Todesminen für die Defias kocht, und wer immer ihm dieses Rezept abgenommen hat, hat nicht höflich gefragt. Zwei Portionen eigenartiges Fleisch, eine Portion schweres Kodofleisch und feine Gewürze, langsam zusammen geschmort, bis der Kodo weich wird und das Eigenartige sich vertieft. Ich kann riechen, was das eigenartige Fleisch einmal war. In Cookies Küche hätte ich es lieber nicht gewusst. Ein Festmahl ist zum Teilen da, also legt es auf eine einzige große Platte und lasst jeden zugreifen. Meine Todeswachen tun das schweigend, vorsichtig, jede lässt ein wenig für die nächste übrig, und das ist mehr, als die Defias je getan haben. Der Geruch füllt die Halle und lockt die Lebenden aus der Stadt darüber herunter, und ich habe aufgehört, sie wegzuschicken. Das Festmahl eines verbrecherischen Murlocs, in der Küche einer toten Frau, gegessen von jedem, der Hunger hat. Ich glaube, Cookie wäre einverstanden. Ich glaube, er hätte gern seine Kelle zurück." },
    [1263067] = { "Mehl, Quellwasser und feine Gewürze, zehn Maß, fünf und vier, für einen Eisenofen, in dessen Rezept überhaupt kein Eisen vorkommt. Ich glaube, der Teig wird in den neuen Ofen gearbeitet und hart gebacken, um ihn einzubrennen, so wie man eine neue Pfanne einbrennt. Man hat mir das Rezept nicht verkauft, nur davon erzählt, ein Goblinhändler, der glaubte, mich damit zu beeindrucken. Das tat er auch. Ich habe es ihm nicht gesagt. Goblins sind unerträglich, wenn man sie beeindruckt, und sie setzen es auf die Rechnung." },
    [1270632] = { "Mehl und sonst nichts, zu kleinen Keksen gebacken für die Geschöpfe, die Abenteurern überallhin folgen. Ich mache sie für die Ratten von Undercity, die sich meinen Respekt verdient haben, und das sind drei. Knetet das Mehl leicht und backt die Kekse hell. Sie riechen nach warmem Brot und nach nichts weiter, und das ist auch gut so, denn ein Haustier, das Gewürze lieben lernt, lässt Euch nie wieder in Ruhe." },
    [1270633] = { "Zwei Eier und ein wenig Mehl, das Eiweiß geschlagen, bis es steht, untergehoben und gebacken, ohne ein einziges Mal die Tür zu öffnen. Von außen könnt Ihr ein Soufflé nicht aufgehen sehen, aber Ihr könnt es riechen: Der Geruch wechselt von nassem Ei zu warmem Brot in dem Augenblick, in dem es seinen Höhepunkt erreicht. Nehmt es dann heraus und tragt es schnell. Ein Soufflé ist ein angehaltener Atem. Es wartet nicht, bis der Gast ausgeredet hat." },
    [1270635] = { "Krebsscheren, geknackt und ausgepult, mit so wenig Mehl gebunden, wie sie gerade zusammenhält, und in kleinen Happen ausgebacken. Das Mehl ist ein Seil, keine Mahlzeit. Nehmt zu viel, und die Happen riechen nach Brot und nach sonst nichts. Nehmt gerade genug, und sie riechen nach dem Meer und der Pfanne. Krebssaison nennt es das Rezept. Meiner Erfahrung nach ist jede Saison Krebssaison, wenn man nah genug am Wasser wohnt." },
    [1283400] = { "Sternenholz brennt heißer und sauberer als gewöhnliches Holz, mit einem Geruch wie Harz und Frost. Das Rezept kam aus den Höhlen des Wehklagens, wo die Druiden falsch geträumt haben, und jemand fand, dass ein besseres Lagerfeuer die Reise wert war. Schichtet es auf dieselbe Weise und lasst es weiter herunterbrennen, bevor Ihr kocht, denn ein heißeres Feuer verzeiht weniger. Wenn die Glut an den Rändern weiß leuchtet, seid Ihr bereit." },
    [1291341] = { "Dicke Holzscheite, langsam im Fangen und langsam im Sterben, ein Feuer für einen ganzen Abend. Legt sie im Viereck mit einer Lücke für die Luft und entzündet das Anmachholz darunter. Dann wartet. Der Geruch verändert sich, wenn es so weit ist, von grünem Rauch zu trockenem, von scharf zu süß. Das ist das Feuer eines Experten, und die Lektion eines Experten: Die beste Hitze ist die, auf die man gewartet hat. Man hat mir dieses Rezept nie verkauft. Ich baue es nach dem, was man mir erzählt hat, und man hat es mir gut erzählt." },
    [1294014] = { "Beeren vom Hyjal, drei Maß davon, langsam mit feinen Gewürzen eingekocht, bis ein Tropfen auf einem kalten Teller Falten wirft, wenn Ihr ihn anstoßt. Der Geruch ist das Beste daran, und das kann ich Euch mit einiger Gewissheit sagen: dunkle Frucht und warme Gewürze, so süß, dass es fast laut ist. Die Bären plündern die Sträucher wegen dieser Beeren, sagt das Rezept. Das würde ich auch, wenn ich ein Bär wäre." },
    [1295805] = { "Ein Eintopf der Küste: Krebs, Murlocaugen und scharfe Gewürze. Die Augen machen die Brühe dick, also lasst sie nicht weg, um jemandes Gefühle zu schonen. Der Krebs kommt am Ende hinein, damit er süß bleibt. Der Geruch ist das Meer, bevor jemand aufgeräumt hat, Salz und Tang und etwas, das noch lebt. Meine Schüler halten sich beim ersten Mal die Nase zu. Beim zweiten Mal bitten sie um eine Schüssel." },
    [1295834] = { "Eber, am Knochen geröstet, mit ein wenig milden Gewürzen und sonst nichts, so wie es Bauernküchen schon immer getan haben. Das Rezept kommt aus den Flusslanden, von jemandem, der offensichtlich hungrige Leute zu versorgen hatte. Röstet ihn, bis das Fett knistert und der Geruch von Fleisch zu Haselnuss wechselt. Verziert ihn nicht. Ein schlichtes Gericht ist ein Versprechen, dass das Fleisch gut ist, und ein Koch, der Dinge hinzufügt, gibt zu, dass es das nicht war." },
    [1319313] = { "Ein Fisch in Rüstung. Die Platten lösen sich mit einem schweren Messer und einer Menge Geduld, und das Fleisch darunter ist fest und blass wie das eines Hummers. Feine Gewürze, mäßige Hitze und keine Eile. Gepanzerte Dinge brauchen Zeit zum Garen, wie die Todeswachen Euch sagen werden, und sie reden dabei nicht von Fisch. Serviert ihn in seinen eigenen Platten, gewaschen. Das bringt die Leute zum Lächeln." },
  },
}
-- (the places Classic Era's client names otherwise, swapped in there)
ns.classicNames = { ["Sturmwind"] = "Stormwind" }
